window.DECKS=[{"id": "wk01-intro", "title": "Week 1 - Course Introduction", "pages": 15}, {"id": "wk01-natural", "title": "Week 1 - Natural Materials", "pages": 41}, {"id": "wk02-engmaterials", "title": "Week 2 - Engineering Materials", "pages": 146}, {"id": "wk03-properties", "title": "Week 3 - Properties of Materials & Selection", "pages": 99}, {"id": "wk04-casting", "title": "Week 4 - Metals: Liquid State Forming (Casting)", "pages": 74}, {"id": "wk05-forming", "title": "Week 5 - Metals: Plastic & Solid State Forming", "pages": 78}, {"id": "wk06-thermoplastics", "title": "Week 6 - Polymers: Thermoplastic Processes", "pages": 65}, {"id": "wk07-thermosets", "title": "Week 7 - Polymers: Thermosets & Composites", "pages": 86}, {"id": "wk08-cutting", "title": "Week 8 - Metals: Cutting & Machining", "pages": 91}, {"id": "wk09-joining", "title": "Week 9 - Joining: Soldering, Brazing, Welding", "pages": 82}, {"id": "wk10-joining", "title": "Week 10 - Joining: Plastics, Adhesives, Fasteners", "pages": 83}, {"id": "wk13-ceramics", "title": "Week 13 - Ceramics, Glass, Carbon, RHMs", "pages": 56}];
window.QUESTIONS=[{"d":"wk01-intro","p":10,"q":"The ID2322 final examination is a:","o":["90-minute closed book written paper","2-hour open book written paper","60-minute closed book online quiz","90-minute open book written paper"],"h":"Check the Final Examination slide.","a":0,"id":0},{"d":"wk01-intro","p":7,"q":"In ID2322, the final examination contributes what percentage of the total grade?","o":["60%","50%","40%","10%"],"h":"CA makes up the remaining 60%.","a":2,"id":1},{"d":"wk01-intro","p":5,"q":"According to the ID2322 syllabus, forging, rolling, extrusion and thermoforming are classed as:","o":["Liquid state forming processes","Plastic state forming processes","Solid state forming processes","Joining processes"],"h":"The material is soft/deformable but not molten.","a":1,"id":2},{"d":"wk01-intro","p":5,"q":"According to the ID2322 syllabus, castings and mouldings are:","o":["Liquid state forming processes","Plastic state forming processes","Solid state forming processes","Machining processes"],"h":"The material is shaped while molten.","a":0,"id":3},{"d":"wk01-intro","p":5,"q":"Cutting, bending and stamping are classified in the syllabus as:","o":["Liquid state forming processes","Plastic state forming processes","Solid state forming processes","Additive processes"],"h":"The material stays solid at room temperature.","a":2,"id":4},{"d":"wk01-natural","p":2,"q":"The smallest part of an element that retains the properties of that element is the:","o":["Molecule","Crystal","Atom","Grain"],"h":"It is the building block of all engineering materials.","a":2,"id":5},{"d":"wk01-natural","p":4,"q":"Organic materials are best defined as materials that:","o":["Come from living things, usually contain carbon, and can decay","Contain no carbon and are formed only through slow geological processes","Are man-made synthetics that do not decompose over time","Are crystalline solids of a fixed chemical composition found in rock"],"h":"Think of wood, cotton, bone and crude oil.","a":0,"id":6},{"d":"wk01-natural","p":5,"q":"Which of the following is an inorganic material?","o":["Silk","Crude oil","Cotton","Sand"],"h":"Inorganic materials are not derived from living things.","a":3,"id":7},{"d":"wk01-natural","p":4,"q":"Which of the following is NOT an organic (biotic) material?","o":["Linoleum","Chitin","Granite","Horn"],"h":"Rocks come from the ground, not from living organisms.","a":2,"id":8},{"d":"wk01-natural","p":6,"q":"Plastics engineers deal primarily with ______ substances.","o":["organic","inorganic","metallic","ceramic"],"h":"Polymers are carbon-based.","a":0,"id":9},{"d":"wk01-natural","p":6,"q":"Metallurgists and ceramists deal primarily with:","o":["Organic substances","Inorganic substances","Biological substances","Polymeric substances"],"h":"Metals and ceramics are not derived from living things.","a":1,"id":10},{"d":"wk01-natural","p":7,"q":"A natural material is any product or physical matter that comes from:","o":["Factories, refineries or laboratories","Plants, animals or the ground","Recycled consumer waste only","Petroleum-based feedstocks only"],"h":"Three natural sources are listed.","a":1,"id":11},{"d":"wk01-natural","p":8,"q":"Clay and porcelain are listed under natural inorganic materials as:","o":["Metals","Stones","Composites","Natural fibres"],"h":"They are mixtures of several minerals.","a":2,"id":12},{"d":"wk01-natural","p":11,"q":"Cork is harvested commercially mainly from the cork oak tree, with which country producing about 50% of the world's cork?","o":["Spain","Portugal","Italy","France"],"h":"An Iberian country famous for wine stoppers.","a":1,"id":13},{"d":"wk01-natural","p":11,"q":"Cork is well suited for wine bottle stoppers mainly because of its:","o":["Elasticity and near-impermeability","High hardness combined with low porosity","High density combined with stiffness","High thermal conductivity and rigidity"],"h":"It must seal tightly and keep liquid in.","a":0,"id":14},{"d":"wk01-natural","p":14,"q":"Hardwood trees are characterised by:","o":["Broad leaves, bearing fruit or nuts, usually dormant in winter","Needle-like leaves, bearing cones, and staying green all year","Always being denser and harder than any softwood species","Growing mainly in cold northern climates with short summers"],"h":"Think of teak or oak versus pine.","a":0,"id":15},{"d":"wk01-natural","p":14,"q":"Which of the following is a softwood?","o":["Teak","Rosewood","Pine","Ramin"],"h":"Softwoods are conifers that bear cones.","a":2,"id":16},{"d":"wk01-natural","p":16,"q":"Which of the following is listed as a South East Asian hardwood?","o":["Spruce","Cedar","Fir","Nyatoh"],"h":"The others are conifers.","a":3,"id":17},{"d":"wk01-natural","p":17,"q":"Plywood, compressed wood board and MDF are examples of:","o":["Wood composites","Natural solid hardwoods","Sawn softwood timbers","Wood-free polymer boards"],"h":"They are made by binding strands, fibres or boards of wood together.","a":0,"id":18},{"d":"wk01-natural","p":17,"q":"MDF stands for:","o":["Multi-Directional Fibreboard","Medium Density Fibreboard","Moulded Density Fibre","Machined Dense Finish"],"h":"It is an engineered wood board.","a":1,"id":19},{"d":"wk01-natural","p":21,"q":"Leather is created through the ______ of animal hides and skins.","o":["Vulcanisation","Tanning","Sintering","Curing"],"h":"The process prevents decomposition.","a":1,"id":20},{"d":"wk01-natural","p":23,"q":"Tanning converts putrescible skin into non-putrescible leather. \"Putrefaction\" refers to:","o":["Decomposition of proteins","Hardening of the collagen fibres","Removal of hair from the hide","Drying and stiffening of the skin"],"h":"Putrescible means it can rot.","a":0,"id":21},{"d":"wk01-natural","p":24,"q":"Which leather is used for items that need to be strong but flexible, such as motorcycle gloves?","o":["Lamb leather","Kangaroo leather","Buffalo leather","Deer skin"],"h":"An Australian animal.","a":1,"id":22},{"d":"wk01-natural","p":24,"q":"Which leather is considered among the finest and most durable in the world?","o":["Cow hide","Sting ray leather","Ostrich leather","Buffalo leather"],"h":"A large flightless bird.","a":2,"id":23},{"d":"wk01-natural","p":22,"q":"In the leather industry, compared to the fur industry:","o":["The hide is a by-product, the meat being worth more","The meat is a by-product, the hide being worth more","Only exotic animals are used, for higher-value skins","The hair is always left attached to the finished hide"],"h":"In the fur industry it is the opposite.","a":0,"id":24},{"d":"wk01-natural","p":27,"q":"Cow/buffalo horn combs are made from keratin. A key benefit claimed for them is:","o":["High electrical conductivity","Zero static electricity","Magnetic properties","Heat resistance above 1000°C"],"h":"Plastic combs cause frizz through this effect.","a":1,"id":25},{"d":"wk01-natural","p":33,"q":"Minerals are:","o":["Natural compounds formed geologically, defined by composition and structure","Any natural material dug out of the ground, including rocks, soils and organic sediments","Man-made crystalline compounds produced by controlled heating","Organic compounds formed by living organisms over long geological periods of time"],"h":"The study of them is mineralogy.","a":0,"id":26},{"d":"wk01-natural","p":34,"q":"To be classified as a \"true\" mineral, a substance must be:","o":["A naturally occurring crystalline solid of defined composition","A naturally occurring liquid or solid of any internal structure","A man-made or natural solid with an amorphous structure","A naturally occurring mixture of rocks and mineraloids"],"h":"Three criteria: solid, crystalline, naturally occurring and homogeneous.","a":0,"id":27},{"d":"wk01-natural","p":35,"q":"On the Mohs scale, hardness is defined as resistance to:","o":["Indentation","Bending","Scratching","Impact"],"h":"You test it by scratching one mineral with another.","a":2,"id":28},{"d":"wk01-natural","p":35,"q":"On the Mohs scale of mineral hardness, which mineral has a hardness of 1?","o":["Talc","Gypsum","Quartz","Calcite"],"h":"The softest mineral, used in powder.","a":0,"id":29},{"d":"wk01-natural","p":35,"q":"Quartz has a Mohs hardness of:","o":["5","6","7","9"],"h":"It sits between orthoclase feldspar and topaz.","a":2,"id":30},{"d":"wk01-natural","p":35,"q":"Corundum (Al2O3), with a Mohs hardness of 9, is the mineral form of:","o":["Silicon carbide","Aluminium oxide","Calcium carbonate","Silicon dioxide"],"h":"Its chemical formula is Al2O3.","a":1,"id":31},{"d":"wk01-natural","p":35,"q":"The Mohs scale is described as a purely ______ scale.","o":["ordinal","linear","logarithmic","absolute"],"h":"Diamond (10) is about 15x harder than quartz (7) in absolute terms.","a":0,"id":32},{"d":"wk01-natural","p":36,"q":"A rock is:","o":["A natural aggregate of minerals and/or mineraloids","A single natural mineral crystal of one composition","A man-made ceramic formed by firing natural clay","An organic sediment formed from plant and animal remains"],"h":"Rocks are mixtures.","a":0,"id":33},{"d":"wk01-natural","p":38,"q":"Granite has begun to supplant marble as a monument material mainly because:","o":["It is more durable against acid rain","It is cheaper and faster to quarry","It is softer and easier to carve finely","It is lighter and easier to transport"],"h":"Marble is a carbonate that is attacked by acid.","a":0,"id":34},{"d":"wk01-natural","p":29,"q":"Good designers design with ecology in mind. This includes:","o":["Not using endangered species as material","Using endangered species for exclusive products","Avoiding all natural materials in every product","Using only metals since they can be recycled"],"h":"Saving wildlife.","a":0,"id":35},{"d":"wk02-engmaterials","p":3,"q":"Engineering materials are classified into which four categories?","o":["Metals, polymers, glasses and woods","Metals, polymers, ceramics and composites","Ferrous, nonferrous, polymers and ceramics","Thermoplastics, thermosets, metals and ceramics"],"h":"Glass is a subset of one of the categories.","a":1,"id":36},{"d":"wk02-engmaterials","p":5,"q":"Which of the following is NOT a typical characteristic of metals?","o":["Crystalline structure","Opaque and lustrous","Poor electrical conductivity","Able to change shape permanently under external forces"],"h":"Think of copper wiring.","a":2,"id":37},{"d":"wk02-engmaterials","p":6,"q":"When two or more metals are combined together, the result is called a(n):","o":["Composite","Alloy","Copolymer","Cermet"],"h":"Brass and bronze are examples.","a":1,"id":38},{"d":"wk02-engmaterials","p":6,"q":"Sterling silver consists of:","o":["77% silver + 23% tin","92.5% silver + 7.5% copper","80% silver + 20% chromium","99.9% pure silver"],"h":"The copper adds hardness.","a":1,"id":39},{"d":"wk02-engmaterials","p":6,"q":"Bell metal is an alloy of:","o":["Copper 77% + tin 23%","Copper 60% + zinc 40%","Nickel 80% + chromium 20%","Silver 92.5% + copper 7.5%"],"h":"It is a type of bronze with high tin content.","a":0,"id":40},{"d":"wk02-engmaterials","p":6,"q":"Nichrome, used for heating elements, is an alloy of:","o":["Nickel and copper","Nickel and chromium","Chromium and iron","Nickel and tin"],"h":"The name gives it away.","a":1,"id":41},{"d":"wk02-engmaterials","p":10,"q":"A metal can best be defined by the nature of its bonds, as:","o":["Solids of atoms held together by a matrix of electrons","Solids of atoms sharing electrons in fixed localised pairs","Long carbon chains linked by weak secondary bonds","Ionic compounds of a metal ion and a non-metal ion"],"h":"The free electrons explain conductivity.","a":0,"id":42},{"d":"wk02-engmaterials","p":11,"q":"When a molten metal solidifies, its atoms arrange in a regular 3-dimensional pattern known as the:","o":["Grain boundary","Space lattice","Dislocation","Amorphous network"],"h":"This orderly arrangement repeats in 3D.","a":1,"id":43},{"d":"wk02-engmaterials","p":12,"q":"The smallest unit that makes up the building block of the space lattice is called the:","o":["Grain","Crystal","Unit cell","Dislocation"],"h":"Also called lattice cell.","a":2,"id":44},{"d":"wk02-engmaterials","p":13,"q":"How many basic unit cells can be identified?","o":["4","7","14","32"],"h":"These are the Bravais lattices.","a":2,"id":45},{"d":"wk02-engmaterials","p":15,"q":"Metals with a body-centred cubic (BCC) unit cell are normally characterised by:","o":["High melting point, high yield strength, low ductility","Low melting point, high ductility and easy cold forming into thin wire","Low plasticity and embrittlement only when cold worked","High ductility and easy deformation on many slip planes at room temperature"],"h":"Tungsten and molybdenum are examples.","a":0,"id":46},{"d":"wk02-engmaterials","p":15,"q":"Which of the following metals crystallises in a BCC structure?","o":["Copper","Aluminium","Tungsten","Zinc"],"h":"A very high melting point metal used in filaments.","a":2,"id":47},{"d":"wk02-engmaterials","p":16,"q":"Metals with an FCC structure tend to be:","o":["Brittle with high melting points","Ductile and easily deformed","Brittle when cold worked","Non-crystalline"],"h":"Copper, aluminium, gold are FCC.","a":1,"id":48},{"d":"wk02-engmaterials","p":16,"q":"Which group lists metals with an FCC arrangement?","o":["Copper, aluminium, lead, gold","Tungsten, molybdenum, vanadium","Beryllium, zinc, titanium, magnesium","Zinc, zirconium, magnesium"],"h":"These are all very ductile metals.","a":0,"id":49},{"d":"wk02-engmaterials","p":17,"q":"Metals with a hexagonal close-packed (HCP) structure, such as zinc, titanium and magnesium, tend to:","o":["Have low plasticity and embrittle when cold worked","Be highly ductile and easily drawn at room temperature","Have the highest melting points and yield strengths","Be non-magnetic and deform on many slip planes"],"h":"Deformation only occurs readily on the 2 basal planes.","a":0,"id":50},{"d":"wk02-engmaterials","p":17,"q":"Which of the following metals has an HCP structure?","o":["Gold","Nickel","Magnesium","Vanadium"],"h":"Beryllium, zinc, titanium, zirconium are also HCP.","a":2,"id":51},{"d":"wk02-engmaterials","p":18,"q":"Metals are good conductors of electricity because:","o":["Electrons are free to move throughout the crystal","Their atoms are packed randomly with large gaps","Their ions are free to move through the lattice","Their electrons are locked in fixed covalent pairs"],"h":"Current flow requires a flow of electrons.","a":0,"id":52},{"d":"wk02-engmaterials","p":20,"q":"In metals, loading tends to cause ______ rather than cleavage of the crystal.","o":["Crazing","Atomic slip","Crosslinking","Sintering"],"h":"Dislocations move along slip planes.","a":1,"id":53},{"d":"wk02-engmaterials","p":22,"q":"Metals are strengthened when dislocations:","o":["Move more freely","Meet more barriers to their motion","Are completely removed by melting","Are aligned in the flow direction"],"h":"The more barriers, the stronger the metal.","a":1,"id":54},{"d":"wk02-engmaterials","p":23,"q":"Adding larger impurity atoms to a pure metal to impede dislocation motion is called:","o":["Solid solution strengthening","Precipitation hardening by ageing","Quench hardening by rapid cooling","Mechanical working by cold rolling"],"h":"The alloying atoms are dissolved in the host lattice.","a":0,"id":55},{"d":"wk02-engmaterials","p":25,"q":"Mechanical working (cold working) strengthens metals by:","o":["Multiplying dislocations that hinder each other","Dissolving larger impurity atoms in the lattice","Trapping solute atoms through rapid quenching","Removing grain boundaries through recrystallisation"],"h":"Bending a paper clip back and forth makes it harder.","a":0,"id":56},{"d":"wk02-engmaterials","p":26,"q":"Precipitation hardening, used for many nonferrous metals, works by:","o":["Heat treatment that makes alloying atoms cluster and block dislocations","Rapid quenching from high temperature that traps carbon atoms in a distorted iron lattice","Cold rolling that multiplies dislocations until they tangle together","Adding larger solute atoms that dissolve evenly throughout the host metal's crystal lattice"],"h":"The alloying element \"collects into a mass\".","a":0,"id":57},{"d":"wk02-engmaterials","p":27,"q":"The most industrially important strengthening mechanism in metals is:","o":["Solid solution strengthening","Precipitation hardening","Quench hardening","Mechanical working"],"h":"It involves rapid cooling and trapped solute atoms.","a":2,"id":58},{"d":"wk02-engmaterials","p":28,"q":"Metals are broadly divided into which two types?","o":["Crystalline and amorphous","Ferrous and nonferrous","Wrought and cast","Light and heavy"],"h":"Based on whether iron is the main element.","a":1,"id":59},{"d":"wk02-engmaterials","p":31,"q":"Iron-carbon alloys with less than 0.005% carbon at room temperature are classed as:","o":["Pure iron","Low carbon steel","Cast iron","Tool steel"],"h":"It is soft and used for magnetic devices and enamelling steels.","a":0,"id":60},{"d":"wk02-engmaterials","p":32,"q":"Steels are defined as iron–carbon alloys with carbon content approximately between:","o":["0.0005–0.005% C","0.006–0.06% C","0.06–2.0% C","More than 2.0% C"],"h":"Above about 2% C the alloys are cast irons.","a":2,"id":61},{"d":"wk02-engmaterials","p":32,"q":"Cast irons contain more than 2% carbon, and are usually shaped by casting because:","o":["The high carbon makes them too brittle to roll, form or shear","They have melting points too low for hot rolling or forging","They are too soft to hold a machined or sheared edge","Their carbon content makes them too ductile to cut cleanly"],"h":"Casting is about the only way to make a useful shape.","a":0,"id":62},{"d":"wk02-engmaterials","p":36,"q":"In the ore-to-steel process, limestone is a common flux used to:","o":["Add carbon to the iron","Remove silica","Cool the blast furnace","Coat the steel with zinc"],"h":"It combines with impurities to form slag.","a":1,"id":63},{"d":"wk02-engmaterials","p":42,"q":"In carbon steel, the principal hardening agent is:","o":["Manganese","Chromium","Carbon","Nickel"],"h":"Other elements are limited to small percentages.","a":2,"id":64},{"d":"wk02-engmaterials","p":43,"q":"In general usage, alloy steels are steels with total alloy additions of less than about:","o":["0.5%","5%","10.5%","20%"],"h":"Used primarily for structural applications.","a":1,"id":65},{"d":"wk02-engmaterials","p":44,"q":"Galvanized steel is:","o":["Zinc-coated steel, applied by hot dipping","Tin-coated steel, applied by electroplating","Chromium-plated steel, applied by electrolysis","Steel alloyed with at least 10.5% chromium"],"h":"It often has paint-adhesion problems.","a":0,"id":66},{"d":"wk02-engmaterials","p":45,"q":"Galvannealed steel differs from galvanized steel because it:","o":["Is heat treated after zinc coating for better paint adhesion","Is coated with tin rather than zinc for better solderability","Is cold rolled after coating to give a thinner, brighter finish","Has its zinc coating pickled off before painting"],"h":"Galvanized + annealed.","a":0,"id":67},{"d":"wk02-engmaterials","p":48,"q":"Tin plate is:","o":["Cold-rolled steel 0.1 to 0.4 mm thick, tin coated or not","Pure tin sheet 0.1 to 0.4 mm thick, rolled from ingot","Hot-rolled steel thicker than 6.4 mm, coated with tin","Zinc-coated steel sheet used mainly for roofing panels"],"h":"Used for cans.","a":0,"id":68},{"d":"wk02-engmaterials","p":49,"q":"\"Free machining\" steels contain additions of:","o":["Sulfur, lead or selenium","Chromium, nickel or molybdenum","Zinc applied by hot dipping","Extra carbon above 2 percent"],"h":"These make chips break easily.","a":0,"id":69},{"d":"wk02-engmaterials","p":50,"q":"Pickling is:","o":["Using acids to remove oxides and scale","Coating steel with a thin layer of zinc","Heat treating steel for paint adhesion","Quenching hot steel in a brine solution"],"h":"A cleaning step after hot rolling.","a":0,"id":70},{"d":"wk02-engmaterials","p":52,"q":"Stainless steels have a minimum chromium content of:","o":["5%","8%","10.5%","18%"],"h":"Chromium forms the passive layer.","a":2,"id":71},{"d":"wk02-engmaterials","p":52,"q":"Which of the following is NOT one of the four major categories of wrought stainless steel?","o":["Austenitic","Ferritic","Martensitic","Pearlitic"],"h":"The fourth is precipitation hardening.","a":3,"id":72},{"d":"wk02-engmaterials","p":54,"q":"Grade 304 stainless steel is often called 18/8 because it contains:","o":["About 18% chromium and 8% nickel","About 18% nickel and 8% chromium","18% carbon and 8% chromium","18% chromium and 8% molybdenum"],"h":"It is austenitic and non-magnetic.","a":0,"id":73},{"d":"wk02-engmaterials","p":54,"q":"Grade 316 stainless steel has superior resistance to salt water compared to 304 mainly due to the addition of:","o":["Molybdenum","Carbon","Zinc","Manganese"],"h":"Used in marine gear and surgical tools.","a":0,"id":74},{"d":"wk02-engmaterials","p":54,"q":"Austenitic grade 304 stainless steel is:","o":["Non-magnetic","Strongly magnetic","Hardenable by quenching","Used mainly for exhaust systems"],"h":"Kitchen sinks are typically 304.","a":0,"id":75},{"d":"wk02-engmaterials","p":55,"q":"Ferritic stainless steels are magnetic and are commonly used for:","o":["Exhaust systems and heat-transfer equipment","Surgical implants and food processing tanks","Cutlery, bearings and turbine blades","High-temper springs and aircraft parts"],"h":"Moderate toughness and corrosion resistance.","a":0,"id":76},{"d":"wk02-engmaterials","p":57,"q":"Which stainless steels are magnetic, can be hardened by heat treatment, and are used for cutlery, bearings and moulds?","o":["Austenitic","Ferritic","Martensitic","Precipitation-hardening"],"h":"Strength/hardness is the primary concern.","a":2,"id":77},{"d":"wk02-engmaterials","p":58,"q":"Precipitation-hardening stainless steels are valued because they:","o":["Reach very high strength with a low-temperature treatment that barely distorts parts","Are the cheapest stainless grades, since they need no heat treatment or alloy additions at all","Are non-magnetic, food-grade steels hardened only by heavy cold working","Have the highest chromium and nickel content, giving them the best salt-water corrosion resistance"],"h":"Used for aircraft components and springs.","a":0,"id":78},{"d":"wk02-engmaterials","p":59,"q":"Tool steels are always ______ to develop their best properties.","o":["Galvanised","Heat treated","Pickled","Cold rolled"],"h":"They are high-alloy, metallurgically clean steels.","a":1,"id":79},{"d":"wk02-engmaterials","p":62,"q":"Which type of tool steel makes good cutting tools because it resists softening at high service temperatures?","o":["Type S (shock-resisting)","Type P (mold steels)","Type T/M (high-speed)","Type H (hot-work)"],"h":"Its name suggests fast cutting.","a":2,"id":80},{"d":"wk02-engmaterials","p":61,"q":"Shock-resisting tool steels (type S) are used for:","o":["Chisels, punches and shear blades","Plastic injection moulds and dies","High-speed lathe and drill tools","Hot-work forging and extrusion dies"],"h":"Strong and tough but less wear resistant.","a":0,"id":81},{"d":"wk02-engmaterials","p":62,"q":"Type P tool steels are created specifically for:","o":["Plastic and die-cast moulds","High-speed cutting tools","Pneumatic chisels and punches","Springs and shear blades"],"h":"P stands for plastic mould.","a":0,"id":82},{"d":"wk02-engmaterials","p":65,"q":"In powder metallurgy, compacting pressures are typically between:","o":["1 and 10 MPa","80 MPa and 1600 MPa","2000 and 5000 MPa","0.1 and 1 MPa"],"h":"The compacted part is then sintered.","a":1,"id":83},{"d":"wk02-engmaterials","p":68,"q":"In powder metallurgy, parts are formed by compaction and then:","o":["Melted and cast","Sintered","Anodised","Pickled"],"h":"Heating below the melting point bonds the particles.","a":1,"id":84},{"d":"wk02-engmaterials","p":69,"q":"Metal injection moulding (MIM) combines:","o":["Plastic injection moulding's shaping with powder metallurgy's materials","Die casting's high production speed with the superior grain-flow strength of closed-die forging","Sand casting's low tooling cost with the precision of machining","Extrusion's continuous constant profiles with the very thin gauges achievable by cold rolling"],"h":"Ideal for small intricate parts like watch links.","a":0,"id":85},{"d":"wk02-engmaterials","p":69,"q":"MIM parts can achieve approximately what percentage of wrought material properties?","o":["50–60%","70–80%","95–98%","100–110%"],"h":"At a much reduced cost for small intricate parts.","a":2,"id":86},{"d":"wk02-engmaterials","p":75,"q":"Aluminium resists corrosion because:","o":["An oxide coating forms on it in air","It contains chromium like stainless steel","It is usually coated with zinc by dipping","Its surface is passivated by its silicon content"],"h":"Its own anticorrosion mechanism.","a":0,"id":87},{"d":"wk02-engmaterials","p":75,"q":"Which of the following is NOT a property of aluminium given in the notes?","o":["High strength-to-weight ratio","Non-sparking","Nonmagnetic","Poor electrical conductivity"],"h":"It is used in power lines.","a":3,"id":88},{"d":"wk02-engmaterials","p":78,"q":"Brass is an alloy of copper and ______, while bronze is an alloy of copper and ______.","o":["zinc; tin","tin; zinc","nickel; tin","zinc; lead"],"h":"Bronze statues, brass plumbing fittings.","a":0,"id":89},{"d":"wk02-engmaterials","p":77,"q":"Which statement about copper is correct?","o":["It has excellent conductivity and corrosion resistance","It has a very high strength-to-weight ratio, which suits it to aircraft structures","It keeps high strength at elevated temperatures","It is the lightest of all the commonly used structural metals in industry"],"h":"Used for wires and pipes.","a":0,"id":90},{"d":"wk02-engmaterials","p":80,"q":"The lightest structural metal available is:","o":["Aluminium","Titanium","Magnesium","Zinc"],"h":"Used for power tool housings and racing wheels.","a":2,"id":91},{"d":"wk02-engmaterials","p":81,"q":"Magnesium alloys provide excellent dent resistance and a high:","o":["Thermal expansion","Damping capacity","Electrical resistance","Melting point"],"h":"They absorb energy elastically.","a":1,"id":92},{"d":"wk02-engmaterials","p":82,"q":"Because magnesium is sensitive to stress concentrations, designs should avoid:","o":["Notches, sharp corners and abrupt section changes","Thick sections, generous radii and gradual tapers","Large radii, ribs and uniform wall thicknesses","Die cast forms and thin-walled housing designs"],"h":"Stress concentrators cause fatigue cracks.","a":0,"id":93},{"d":"wk02-engmaterials","p":83,"q":"Titanium has the highest tensile-strength-to-density ratio of any pure metal. Compared to steel it is:","o":["As strong but about 45% lighter","Stronger but about twice as heavy","Weaker but about 80% lighter","Equally strong and equally dense"],"h":"Named after the Titans.","a":0,"id":94},{"d":"wk02-engmaterials","p":83,"q":"Titanium is ideal for medical implants mainly because it:","o":["Is biocompatible and corrosion resistant","Is the cheapest and most easily cast metal","Is magnetic and so easy to locate in the body","Has a low melting point for easy shaping"],"h":"It forms a protective oxide surface layer.","a":0,"id":95},{"d":"wk02-engmaterials","p":86,"q":"Zinc's excellent corrosion resistance leads to its use as:","o":["An alloying element in stainless steel","A coating for steel (galvanizing)","A filament material","Structural beams"],"h":"Zinc alloy is also popular for die casting.","a":1,"id":96},{"d":"wk02-engmaterials","p":89,"q":"Which one of the following is NOT a typical characteristic of polymers compared to metals?","o":["Long molecular chains with carbon backbones","Generally low thermal conductivity","High electrical conductivity","Generally lower strength and unsuitable for high-temperature use"],"h":"Polymers are often used as electrical insulators.","a":2,"id":97},{"d":"wk02-engmaterials","p":93,"q":"Polymers are classified in the notes into:","o":["Thermoplastics, thermosets and composites","Metals, ceramics, polymers and composites","Amorphous and crystalline grades only","Rubbers, fibres and engineering resins"],"h":"Composites here use a polymer matrix.","a":0,"id":98},{"d":"wk02-engmaterials","p":95,"q":"Thermoplastics can be classified into:","o":["Amorphous, crystalline and liquid crystalline","Ferritic, austenitic, martensitic and precipitation-hardening types","Random, alternating, block and graft types","Thermosets, elastomers, plastomers and engineering resins"],"h":"Based on how ordered the polymer chains are.","a":0,"id":99},{"d":"wk02-engmaterials","p":96,"q":"Which of the following is an amorphous thermoplastic?","o":["Nylon","Polypropylene","Polycarbonate","Acetal"],"h":"Amorphous plastics can be intrinsically transparent.","a":2,"id":100},{"d":"wk02-engmaterials","p":96,"q":"Amorphous thermoplastics are characterised by:","o":["A broad softening range and possible transparency","A sharp melting point and anisotropic shrinkage","Retained molecular order in the melt phase","No glass transition and a high crystallinity"],"h":"Think of clear polycarbonate.","a":0,"id":101},{"d":"wk02-engmaterials","p":98,"q":"Thermosetting polymers are amorphous because:","o":["Crosslinking prevents crystallisation","Their chains are long and slender","They are always cooled very quickly","They have no carbon backbone at all"],"h":"Their chains are tied together.","a":0,"id":102},{"d":"wk02-engmaterials","p":98,"q":"Thermosetting polymers, when heated above Tg:","o":["Do not melt but will degrade","Melt into a free-flowing liquid","Recrystallise into a harder form","Soften and can be remoulded"],"h":"They cannot be remelted.","a":0,"id":103},{"d":"wk02-engmaterials","p":99,"q":"Which of the following is a crystalline thermoplastic?","o":["ABS","PVC","Polystyrene","Polypropylene"],"h":"Acetal, nylon, polyethylene, polyester are others.","a":3,"id":104},{"d":"wk02-engmaterials","p":100,"q":"Compared with amorphous thermoplastics, crystalline thermoplastics have:","o":["A sharp, higher melting point and anisotropic shrinkage","A broad softening range, consistent shrinkage and intrinsic transparency","Lower chemical resistance and lower stiffness","No melting point at all, because their chains are crosslinked into a network"],"h":"Organised chain packing.","a":0,"id":105},{"d":"wk02-engmaterials","p":99,"q":"Crystalline thermoplastics are stronger and stiffer than fully noncrystalline materials, but they are:","o":["More transparent","Less impact resistant","Less chemically resistant","Lower in melting temperature"],"h":"There is a trade-off.","a":1,"id":106},{"d":"wk02-engmaterials","p":103,"q":"Liquid crystalline polymers (LCPs) have the ______ shrinkage and warpage of the three types of thermoplastics.","o":["lowest","highest","same","most unpredictable"],"h":"They retain significant order in the melt phase.","a":0,"id":107},{"d":"wk02-engmaterials","p":105,"q":"Plasticizers are added to plastics to:","o":["Decrease modulus, increase flexibility","Increase modulus, stiffness and creep resistance","Increase electrical conductivity","Reduce UV yellowing and fading in outdoor use"],"h":"Think of flexible PVC hose.","a":0,"id":108},{"d":"wk02-engmaterials","p":105,"q":"Particulate fillers such as silica, wood flour and glass balls are added to plastics to:","o":["Raise modulus and heat resistance, and cut cost","Make the plastic transparent and more flexible","Lower the melt temperature for easier moulding","Reduce stiffness and improve impact strength"],"h":"They also can increase electrical conductivity.","a":0,"id":109},{"d":"wk02-engmaterials","p":106,"q":"Aramid fibres are:","o":["Aromatic polyamide fibres","Alumina-reinforced glass fibres","Carbon nanotube-based fibres","Natural plant cellulose fibres"],"h":"Kevlar is an example.","a":0,"id":110},{"d":"wk02-engmaterials","p":109,"q":"A copolymer contains:","o":["One monomer type only","Two different monomers","A physical mixture of two polymers","Three different repeating units"],"h":"Its properties may differ completely from the homopolymers.","a":1,"id":111},{"d":"wk02-engmaterials","p":110,"q":"A copolymer with the arrangement -A-B-A-B-A-B- is a(n):","o":["Alternating copolymer","Random copolymer","Block copolymer","Graft-type terpolymer"],"h":"Units alternate regularly.","a":0,"id":112},{"d":"wk02-engmaterials","p":110,"q":"A copolymer with long runs like -A-A-A-A-B-B-B-B-A-A-A- is a:","o":["Random copolymer","Alternating copolymer","Block copolymer","Terpolymer"],"h":"Units come in blocks.","a":2,"id":113},{"d":"wk02-engmaterials","p":110,"q":"A copolymer with a main chain of A and side chains of B attached is a:","o":["Block copolymer","Random copolymer","Graft copolymer","Blend"],"h":"The B branches are \"grafted\" on.","a":2,"id":114},{"d":"wk02-engmaterials","p":111,"q":"Polymer blends (alloys) are made by:","o":["Chemically polymerising two monomers together","Physically mixing two or more polymers","Adding fillers to a resin","Crosslinking a thermoset"],"h":"Properties are usually intermediate between constituents.","a":1,"id":115},{"d":"wk02-engmaterials","p":113,"q":"ABS is an example of a:","o":["Homopolymer","Copolymer","Terpolymer","Thermoset"],"h":"It has three different repeating units.","a":2,"id":116},{"d":"wk02-engmaterials","p":113,"q":"ABS stands for:","o":["Acrylonitrile butadiene styrene","Acrylic butyl silicone","Amorphous blended styrene acrylate","Acetal butadiene styrene"],"h":"The B is a rubber that adds toughness.","a":0,"id":117},{"d":"wk02-engmaterials","p":114,"q":"ABS is tough because it contains microscopic particles of:","o":["Polybutadiene rubber","Glass microspheres","Carbon black powder","Precipitated silica"],"h":"The rubber phase absorbs impact.","a":0,"id":118},{"d":"wk02-engmaterials","p":118,"q":"For thin-walled injection moulded sections, the better choice is a:","o":["Lower-molecular-weight / lower-viscosity grade","Higher-molecular-weight / higher-viscosity grade","Thermoset grade","Glass-filled grade only"],"h":"It flows more easily into thin sections.","a":0,"id":119},{"d":"wk02-engmaterials","p":118,"q":"Higher-molecular-weight resin grades offer:","o":["Greater toughness and chemical resistance","Easier mould filling and faster moulding cycle times","Lower melt viscosity for thin walls","Lower cost, easier colouring and better surface gloss"],"h":"Longer chains, stiffer flow.","a":0,"id":120},{"d":"wk02-engmaterials","p":121,"q":"Common problems from extended UV exposure of thermoplastics are:","o":["Colour shift, yellowing and loss of properties","Increased stiffness, hardness and surface gloss","Increased electrical conductivity and static","Crystallisation and higher melting temperature"],"h":"UV stabilisers are used to prevent this.","a":0,"id":121},{"d":"wk02-engmaterials","p":124,"q":"The hairline grooves on a moulded part where flow fronts join during filling are called:","o":["Weld (knit) lines","Sink marks","Flow-front flash lines","Short shots"],"h":"They can cut tensile strength by more than 50%.","a":0,"id":122},{"d":"wk02-engmaterials","p":125,"q":"Resins can suffer more than ____ loss of tensile strength at a weld line.","o":["5%","20%","50%","90%"],"h":"A significant drop.","a":2,"id":123},{"d":"wk02-engmaterials","p":126,"q":"Residual stresses in moulded thermoplastics are caused by:","o":["Uneven cooling, differential shrinkage or frozen-in flow","Adding UV stabilisers and colour pigments to the base resin","Using a high-molecular-weight grade for the part","Adding glass fillers that raise the modulus and stiffness of the part"],"h":"They reduce impact strength and dimensional stability.","a":0,"id":124},{"d":"wk02-engmaterials","p":127,"q":"In injection moulding, mechanical properties are generally:","o":["Lower across the flow than along it","Higher across the flow than along it","Identical in every direction","Set only by the mould temperature"],"h":"Polymer chains align with flow.","a":0,"id":125},{"d":"wk02-engmaterials","p":128,"q":"Fibre-filled materials generally have shrinkage in the cross-flow direction that is:","o":["2 to 3 times that in the flow direction","About half that in the flow direction","Equal to that in the flow direction","Negligible compared with flow direction"],"h":"Fibres align with flow and restrain shrinkage along it.","a":0,"id":126},{"d":"wk02-engmaterials","p":132,"q":"According to the polymer selection table, which polymer is \"usually white\"?","o":["ABS","Polycarbonate","Delrin (acetal)","Polystyrene"],"h":"It has good intricate design capability.","a":2,"id":127},{"d":"wk02-engmaterials","p":133,"q":"Lexan and Makrolon are trade names for:","o":["Polypropylene","Polycarbonate","LDPE","ABS"],"h":"A tough transparent amorphous plastic.","a":1,"id":128},{"d":"wk02-engmaterials","p":135,"q":"Ceramics are formed from a combination of:","o":["Metals with non-metals such as oxygen, nitrogen or carbon","Two or more metals melted together and alloyed in a crucible","Long carbon chains crosslinked into a network","A polymer matrix holding a fibre or particulate reinforcement in place"],"h":"Oxides, nitrides and carbides.","a":0,"id":129},{"d":"wk02-engmaterials","p":135,"q":"Ceramics typically have:","o":["High compressive strength, poor plasticity","High plasticity, low compressive strength","Good electrical and thermal conductivity","Low heat resistance and high ductility"],"h":"They are brittle.","a":0,"id":130},{"d":"wk02-engmaterials","p":140,"q":"Composites are made from two or more materials, where one acts as the ______ to hold the ______.","o":["matrix; reinforcement","reinforcement; matrix","resin; filler","substrate; plasticiser"],"h":"Concrete holds steel bars.","a":0,"id":131},{"d":"wk02-engmaterials","p":141,"q":"Particulate composites such as cermets are typically:","o":["Hard and abrasion resistant","Light, flexible and tough","Transparent and insulating","Highly ductile and malleable"],"h":"Used for cutting tools.","a":0,"id":132},{"d":"wk02-engmaterials","p":144,"q":"Epoxy resin in composites is noted for being:","o":["A transparent matrix used in aerospace","A reinforcing fibre used in boat hulls","A thermoplastic substrate for laminates","An opaque filler used to lower cost"],"h":"It acts as a structural glue.","a":0,"id":133},{"d":"wk02-engmaterials","p":144,"q":"In a common composite, fiberglass, carbon fibre and Kevlar serve as the:","o":["Substrate (reinforcement)","Resin binding the layers","Matrix holding the fibres","Plasticiser for flexibility"],"h":"Polyester and epoxy are the resins.","a":0,"id":134},{"d":"wk02-engmaterials","p":74,"q":"Which of the following are nonferrous metals?","o":["White cast iron, copper and stainless steel","Copper, aluminum and tin","Low carbon steel, white cast iron and tool steel","Silver, zinc and mild steel"],"h":"Nonferrous means iron is not the main constituent.","a":1,"id":135},{"d":"wk03-properties","p":4,"q":"How many major groups of properties are considered when selecting a material?","o":["3","4","6","8"],"h":"Physical, mechanical, technological, chemical, economic, aesthetic.","a":2,"id":136},{"d":"wk03-properties","p":5,"q":"Which of the following is primarily a technological property?","o":["Density","Tensile strength","Weldability","Corrosion resistance"],"h":"Technological properties describe behaviour during processing.","a":2,"id":137},{"d":"wk03-properties","p":4,"q":"Density, melting point and thermal conductivity are examples of:","o":["Physical properties","Mechanical properties","Technological properties","Economic properties"],"h":"Inherent aspects not easily altered.","a":0,"id":138},{"d":"wk03-properties","p":4,"q":"Hardness, toughness, creep resistance and fatigue resistance are:","o":["Physical properties","Mechanical properties","Chemical properties","Aesthetic properties"],"h":"They describe response to load.","a":1,"id":139},{"d":"wk03-properties","p":5,"q":"Resistance to oxidation, corrosion and solvents are classed as:","o":["Physical properties","Technological properties","Chemical properties","Economic properties"],"h":"Reactions with the environment.","a":2,"id":140},{"d":"wk03-properties","p":5,"q":"Machinability, castability, forgeability and brazeability are:","o":["Technological properties","Mechanical properties","Aesthetic properties","Physical and chemical properties"],"h":"How easily the material can be fabricated.","a":0,"id":141},{"d":"wk03-properties","p":5,"q":"Surface texture and the ability to accept special finishing are:","o":["Economic properties","Technological properties","Aesthetic properties","Chemical properties"],"h":"Appearance-related.","a":2,"id":142},{"d":"wk03-properties","p":3,"q":"Polyethylene is used as a wire coating material because of its:","o":["Electrical insulation and flexibility","High thermal conductivity and stiffness","High hardness and abrasion resistance","High density and flame resistance"],"h":"The copper inside conducts; the coating must insulate.","a":0,"id":143},{"d":"wk03-properties","p":8,"q":"Which statement best distinguishes physical from mechanical properties?","o":["Physical properties are not easily altered; mechanical ones can be changed by heat treatment","Mechanical properties are not easily altered; physical ones can be changed by heat treatment","Both physical and mechanical properties are fixed once the material is produced","Physical properties apply only to metals, mechanical properties only to polymers"],"h":"Density stays put; hardness can be changed.","a":0,"id":144},{"d":"wk03-properties","p":8,"q":"Density is defined as:","o":["Weight per unit length","Mass / Volume","Volume / Mass","Load / Area"],"h":"Units g/cm3 or kg/m3.","a":1,"id":145},{"d":"wk03-properties","p":11,"q":"Thermal conductivity is expressed in units of:","o":["S/m","W/(m·K)","N/mm²","g/cm³"],"h":"Watts per metre-kelvin.","a":1,"id":146},{"d":"wk03-properties","p":12,"q":"Which material has the highest thermal conductivity at 25°C according to the notes?","o":["Silver (429 W/mK)","Copper (401 W/mK)","Aluminium (205 W/mK)","Cork board (0.07 W/mK)"],"h":"It edges out copper.","a":0,"id":147},{"d":"wk03-properties","p":13,"q":"Electrical conductivity is expressed in SI units of:","o":["Siemens per metre (S/m)","Ohms per square metre","Watts per metre-kelvin","Volts per metre (V/m)"],"h":"Copper is about 5.96 x 10^7 of these units.","a":0,"id":148},{"d":"wk03-properties","p":14,"q":"Relative to annealed copper (100), which metal has the highest relative electrical conductivity?","o":["Silver (106)","Gold (65)","Aluminium (63)","Steel (3-15)"],"h":"Silver is the best electrical and thermal conductor.","a":0,"id":149},{"d":"wk03-properties","p":15,"q":"Copper is chosen for wires inside electrical cables because it is an excellent conductor and is:","o":["Ductile, so it draws easily into thin wire","Hard, so it resists nicks during installation","Magnetic, so it shields the signal it carries","Brittle, so it snaps cleanly when cut to length"],"h":"Wire drawing requires a tensile-deformation property.","a":0,"id":150},{"d":"wk03-properties","p":16,"q":"Generally, the coefficient of thermal expansion is ______ to the melting point; ______ is a significant exception.","o":["inversely proportional; steel","directly proportional; aluminium","inversely proportional; copper","unrelated; glass"],"h":"Higher melt-temperature materials expand less.","a":0,"id":151},{"d":"wk03-properties","p":17,"q":"Ferromagnetism results from the alignment of which atoms into domains?","o":["Copper, zinc and tin","Iron, nickel and cobalt","Aluminium, magnesium and titanium","Gold, silver and platinum"],"h":"The three common magnetic metals.","a":1,"id":152},{"d":"wk03-properties","p":19,"q":"The three common forms of strength are:","o":["Tensile, compressive and shear","Tensile, hardness and fatigue","Elastic, plastic and creep","Impact, bending and torsion"],"h":"Pulling, pushing and sliding.","a":0,"id":153},{"d":"wk03-properties","p":19,"q":"Unit stress (σ) is defined as:","o":["Deformation per unit length","Applied load per unit area","Load per unit volume","Energy absorbed per unit area"],"h":"Expressed in N/mm² (MPa).","a":1,"id":154},{"d":"wk03-properties","p":20,"q":"Strain (ε) is expressed as:","o":["Deformation per unit original length","Applied load per unit cross-sectional area","Newtons of force per metre of length","Change in mass as a percentage of the original"],"h":"It is dimensionless.","a":0,"id":155},{"d":"wk03-properties","p":22,"q":"Elasticity describes:","o":["Recovery of original shape once stress is removed","Permanent deformation without rupture under load","Resistance to scratching, wear and indentation","Gradual deformation under a sustained load"],"h":"A rubber band.","a":0,"id":156},{"d":"wk03-properties","p":23,"q":"When stretched bubble gum thins out and changes cross section, this is called:","o":["Creep","Necking","Spalling","Crazing"],"h":"It precedes fracture in ductile tensile tests.","a":1,"id":157},{"d":"wk03-properties","p":26,"q":"On a stress-strain curve, point A (end of the linear region) is called the:","o":["Proportional limit","Tensile strength","Fracture point","Lower yield point"],"h":"Below it, the material recovers fully.","a":0,"id":158},{"d":"wk03-properties","p":27,"q":"In practice, the \"yield point\" of a steel refers to the:","o":["Upper yield point","Lower yield point","Fracture point","Proportional limit"],"h":"Points B and C are the upper and lower yield points.","a":0,"id":159},{"d":"wk03-properties","p":28,"q":"On the stress-strain curve, the maximum stress before fracture (point D) is the:","o":["Tensile strength","Upper yield point","0.2% proof stress","Proportional limit"],"h":"Fracture occurs later at point E.","a":0,"id":160},{"d":"wk03-properties","p":29,"q":"Which materials do NOT exhibit a marked yield point, but a smooth elastic-to-plastic transition?","o":["Mild steel","Cast iron and aluminium","Low carbon steel only","All ductile steels"],"h":"Mild steel shows a clear discontinuity.","a":1,"id":161},{"d":"wk03-properties","p":31,"q":"Proof stress is quoted to denote yield strength because:","o":["Many materials show no clear yield point in testing","It is always higher than the ultimate tensile strength","It is a measure of surface hardness rather than strength","It applies only to polymers, which never yield"],"h":"Aluminium's curve has no obvious yield.","a":0,"id":162},{"d":"wk03-properties","p":32,"q":"The modulus of elasticity (E) is a measure of a material's:","o":["Hardness","Stiffness","Ductility","Toughness"],"h":"It is the slope of the linear part of the stress-strain curve.","a":1,"id":163},{"d":"wk03-properties","p":32,"q":"Plasticity is the ability of a material to:","o":["Deform permanently without rupture","Recover its shape after load removal","Resist penetration by a hard indenter","Absorb energy under a sudden impact"],"h":"Bubble gum stays deformed.","a":0,"id":164},{"d":"wk03-properties","p":33,"q":"Ultimate tensile strength is calculated by dividing the maximum load by the:","o":["Original cross-sectional area","Final (necked) cross-sectional area","Gauge length","Specimen volume"],"h":"It uses the starting dimensions.","a":0,"id":165},{"d":"wk03-properties","p":36,"q":"Concrete is used for building foundations because it has:","o":["Good compressive strength","High tensile strength","High ductility and toughness","Good torsional strength"],"h":"Foundations are squeezed, not pulled.","a":0,"id":166},{"d":"wk03-properties","p":37,"q":"In bending, the outside fibres of a beam are in ______ and the inside fibres in ______.","o":["tension; compression","compression; tension","shear; tension","torsion; compression"],"h":"The outer surface stretches.","a":0,"id":167},{"d":"wk03-properties","p":38,"q":"Crankshafts and propeller shafts must have superior:","o":["Compressive strength","Torsional strength","Hardness","Thermal conductivity"],"h":"They are twisted about their longitudinal axis.","a":1,"id":168},{"d":"wk03-properties","p":42,"q":"Ductility is the ability of a material to undergo plastic deformation by ______ without fracturing.","o":["tension","compression","scratching","impact"],"h":"Measured in a tensile test.","a":0,"id":169},{"d":"wk03-properties","p":45,"q":"Malleability differs from ductility because malleability is associated with:","o":["Compressive deformation","Tensile deformation","Elastic recovery after loading","Scratch resistance"],"h":"Forging and rolling rely on it.","a":0,"id":170},{"d":"wk03-properties","p":45,"q":"Drawing a wire relies mainly on a material's:","o":["Ductility","Malleability","Hardness","Brittleness"],"h":"Wire is pulled through a die.","a":0,"id":171},{"d":"wk03-properties","p":46,"q":"Which metal is malleable but NOT ductile?","o":["Gold","Copper","Lead","Silver"],"h":"It can be hammered flat but tears when pulled.","a":2,"id":172},{"d":"wk03-properties","p":47,"q":"Hardness is the ability of a material to withstand:","o":["Penetration, scratching or wear","Twisting about its long axis","Repeated cyclic loading below the UTS","Sustained high temperatures"],"h":"A ball bearing will dent clay but not glass.","a":0,"id":173},{"d":"wk03-properties","p":49,"q":"Which three hardness scales are most commonly used for engineering materials?","o":["Brinell, Vickers and Rockwell","Mohs, Knoop and Shore","Charpy, Izod and Brinell","Rockwell, Charpy and Scleroscope"],"h":"They are the first three in the list.","a":0,"id":174},{"d":"wk03-properties","p":51,"q":"Brittleness is the opposite of:","o":["Hardness","Ductility","Strength","Density"],"h":"A brittle material fractures with no plastic deformation.","a":1,"id":175},{"d":"wk03-properties","p":51,"q":"Which of the following are typical brittle materials?","o":["Hardened steels, cast irons, ceramics","Mild steel, copper and gold","Aluminium, lead, tin and annealed brass","Rubber, nylon and polyethylene"],"h":"Brittleness is associated with extreme hardness.","a":0,"id":176},{"d":"wk03-properties","p":51,"q":"Compared with mild steel, high tensile steel is:","o":["More brittle","More ductile","Softer","Lower in strength"],"h":"Brittleness is not related to tensile strength.","a":0,"id":177},{"d":"wk03-properties","p":52,"q":"Impact strength is associated with toughness, which depends mainly on:","o":["Hardness and colour","Ductility and strength","Density and melting point","Thermal and electrical conductivity"],"h":"Tough materials absorb energy before breaking.","a":1,"id":178},{"d":"wk03-properties","p":52,"q":"The two main forms of impact test are:","o":["Brinell and Vickers","Charpy and Izod","Rockwell and Knoop","Tensile and creep"],"h":"Both use a swinging pendulum.","a":1,"id":179},{"d":"wk03-properties","p":53,"q":"In the Izod impact test, the specimen is:","o":["Supported horizontally at both ends and struck behind the notch","Gripped vertically in a vice and struck just above the notch","Loaded in tension slowly","Indented with a diamond"],"h":"The Charpy specimen is horizontal.","a":1,"id":180},{"d":"wk03-properties","p":53,"q":"In the Charpy impact test, the specimen is:","o":["Supported horizontally at both ends and struck behind the notch","Gripped vertically in a vice by one end and struck just above the notch","Clamped at one end and twisted slowly until it fractures","Supported on a flat anvil and indented with a hardened steel ball under load"],"h":"It is a simply supported beam.","a":0,"id":181},{"d":"wk03-properties","p":54,"q":"In Charpy and Izod tests, the energy absorbed in breaking the specimen is measured by:","o":["The difference in pendulum swing height","The depth and diameter of the indentation","The number of load cycles to fracture","The elongation of the specimen at break"],"h":"Some energy is used up breaking it.","a":0,"id":182},{"d":"wk03-properties","p":56,"q":"Failure caused by repeated or cyclic stressing below the tensile strength is called:","o":["Creep","Fatigue failure","Brittle fracture","Spalling"],"h":"Bending a wire back and forth.","a":1,"id":183},{"d":"wk03-properties","p":57,"q":"Which of the following is a typical example of fatigue failure?","o":["Connecting rods, crane hooks and aircraft bodies","Turbine blades under constant load at high temperature","Glass shattering when dropped","A wire being drawn"],"h":"These parts see repeated load cycles.","a":0,"id":184},{"d":"wk03-properties","p":59,"q":"Creep is best described as:","o":["Slow plastic deformation under sustained load, often when hot","Sudden fracture under an impact load at low service temperatures","Failure from repeated fluctuating stresses below the UTS","Loss of strength and colour caused by long exposure to UV radiation"],"h":"Turbine blades and boiler tubes.","a":0,"id":185},{"d":"wk03-properties","p":62,"q":"Creep can also occur at room temperature, for example in:","o":["A machine table sagging under its own weight","A glass window cracking on a cold morning","A rubber band snapping back when released","A bolt stretching briefly while being tightened"],"h":"Prolonged service of structural beams.","a":0,"id":186},{"d":"wk03-properties","p":70,"q":"Materials selection is an interdependent consideration between which three basic elements?","o":["Product design, material and manufacture","Material cost, colour and product weight","Strength, hardness and toughness of the part","Metals, polymers and ceramics available"],"h":"Fig. 1 shows three linked circles.","a":0,"id":187},{"d":"wk03-properties","p":75,"q":"According to the general characteristics table, ceramics are:","o":["Strong, brittle, refractory and insulating","Weak, compliant, durable and insulating","Strong, stiff, tough and electrically conducting","Weak, temperature-sensitive and conducting"],"h":"Refractory means heat resisting.","a":0,"id":188},{"d":"wk03-properties","p":75,"q":"According to the general characteristics table, plastics are:","o":["Weak, compliant, temperature-sensitive and insulating","Strong, stiff, tough and electrically conducting","Strong, brittle, refractory and electrically insulating","Tough, stiff, heat resistant and thermally conducting"],"h":"They are soft and melt easily.","a":0,"id":189},{"d":"wk03-properties","p":76,"q":"An exception to the generalisation that metals are tough is that they:","o":["Can be very brittle at low temperatures","Lose all ductility at high temperatures","Cannot conduct heat when heavily alloyed","Degrade quickly under UV exposure"],"h":"Think of the Titanic's hull steel in icy water.","a":0,"id":190},{"d":"wk03-properties","p":79,"q":"Corrosion resistance, machinability and formability are examples of:","o":["Fundamental parameters","Ranking parameters","Physical constants","Design calculation inputs"],"h":"They can only rank materials in order of superiority.","a":1,"id":191},{"d":"wk03-properties","p":79,"q":"Fundamental parameters such as electrical resistivity have the advantage that they:","o":["Can be used directly in design calculations","Can only place materials in a ranked order","Measure the overall response to a process","Are cheaper to measure than ranking tests"],"h":"They measure basic properties.","a":0,"id":192},{"d":"wk03-properties","p":78,"q":"Weldability cannot be measured with a single parameter because:","o":["It is the overall response to a process","It is a fixed physical property like density","It applies only to ceramics and glasses","It is purely an aesthetic judgement"],"h":"It is a ranking-type property.","a":0,"id":193},{"d":"wk03-properties","p":81,"q":"Which primary process is probably the most widely applicable?","o":["Forging","Machining","Casting","Powder metallurgy"],"h":"From 20 g zinc toys to 150-ton cast iron crushers.","a":2,"id":194},{"d":"wk03-properties","p":84,"q":"Injection moulding of polymers is described in the notes as essentially a:","o":["Forging process","Die casting process","Sintering process","Machining process"],"h":"Molten material is forced into a mould.","a":1,"id":195},{"d":"wk03-properties","p":85,"q":"Oxide ceramics, being brittle, must be formed by:","o":["Rolling and forging","Powder methods","Deep drawing","Extrusion of molten material"],"h":"Like sintering.","a":1,"id":196},{"d":"wk03-properties","p":87,"q":"Machining is usually a secondary process that:","o":["Follows forming but precedes joining and finishing","Precedes casting and forging of the raw stock","Is the final step, performed after joining, finishing and painting","Replaces forming as the primary shaping step"],"h":"It refines a formed part.","a":0,"id":197},{"d":"wk03-properties","p":88,"q":"Annealing is used to:","o":["Soften a metal and remove the effects of cold work","Harden a metal by heating then rapidly quenching it","Join ceramic parts by heating them under pressure","Coat steel with a protective layer of molten zinc"],"h":"The opposite of work hardening.","a":0,"id":198},{"d":"wk03-properties","p":88,"q":"The joining of ceramics is accomplished by:","o":["Arc welding","Soldering","Sintering","Riveting"],"h":"Same as how ceramic powders are consolidated.","a":2,"id":199},{"d":"wk03-properties","p":88,"q":"Which thermosets can be welded?","o":["Only those with little cross-linking","All thermosets, at high enough heat","None at all, under any conditions","Only the fibre-reinforced grades"],"h":"Heavy crosslinking prevents melting.","a":0,"id":200},{"d":"wk03-properties","p":90,"q":"Porcelain is noted for its ability to:","o":["Resist almost all acids","Conduct electricity","Absorb water and swell","Be easily welded"],"h":"Ceramics are chemically stable.","a":0,"id":201},{"d":"wk03-properties","p":90,"q":"Although polymers are generally chemically stable, absorbed water will:","o":["Change their properties and cause swelling","Increase their electrical conductivity and static build-up","Harden and embrittle them permanently","Make them more transparent, glossy and scratch resistant"],"h":"Nylon is a classic example.","a":0,"id":202},{"d":"wk03-properties","p":91,"q":"Ceramics are very stable at high temperatures, but under rapid temperature fluctuations they can suffer:","o":["Creep","Spalling","Necking","Depolymerisation"],"h":"Flakes break off from thermal shock.","a":1,"id":203},{"d":"wk03-properties","p":92,"q":"Heating can activate ______ in polymers, reducing performance.","o":["Crystallisation","Depolymerisation","Vulcanisation","Precipitation hardening"],"h":"Chains break down.","a":1,"id":204},{"d":"wk03-properties","p":93,"q":"Radiation damage in metals usually:","o":["Raises hardness and lowers ductility","Softens the metal in the same way as annealing","Increases ductility and toughness","Causes swelling, loss of mass and surface pitting"],"h":"Annealing can reverse it.","a":0,"id":205},{"d":"wk03-properties","p":93,"q":"Commercial use has been made of UV radiation on polyethylene because it:","o":["Causes branching that improves stability in boiling water","Makes it transparent enough to be used in optical lens applications","Removes crosslinks so it can be recycled more easily","Makes it electrically conductive for antistatic packaging uses"],"h":"Radiation can have a beneficial effect.","a":0,"id":206},{"d":"wk03-properties","p":94,"q":"The total cost of a component considered in economic requirements includes:","o":["Raw material, fabrication and availability","Raw material cost only, before processing","Labour cost only, since material is minor","Shipping and storage costs of the stock"],"h":"Availability affects completion date.","a":0,"id":207},{"d":"wk03-properties","p":95,"q":"The cost of a raw metallic material is often associated with:","o":["How complex it is to extract and prepare","How plentiful its ore is in the earth","Its colour and surface appearance","Its density and weight per unit volume"],"h":"Plentiful ore does not mean cheap.","a":0,"id":208},{"d":"wk03-properties","p":96,"q":"Using more expensive pre-hardened steels can reduce final cost because:","o":["It eliminates heat treatment and its distortion","It is much easier to cast into complex near-net shapes","It needs no machining after delivery","It is lighter, so less material needs to be bought per part"],"h":"A more expensive material may permit simpler processing.","a":0,"id":209},{"d":"wk04-casting","p":3,"q":"The three ways to form metals are:","o":["Liquid, plastic and solid state forming","Casting, moulding and 3D printing","Hot, warm and cold forming","Primary, secondary and tertiary forming"],"h":"Classified by the state of the metal during forming.","a":0,"id":210},{"d":"wk04-casting","p":4,"q":"Casting is often the most economical way to manufacture:","o":["A complex object needing few secondary operations","Thin flat sheets of a uniform and closely controlled thickness","Long continuous profiles of constant section","Fine wire drawn to a precise and consistent diameter"],"h":"One of the earliest manufacturing processes.","a":0,"id":211},{"d":"wk04-casting","p":5,"q":"Problems associated with casting include a tendency toward:","o":["Porous structure and warpage","Work hardening","Excessive ductility","Anisotropic fibre orientation"],"h":"Gas and shrinkage cause defects.","a":0,"id":212},{"d":"wk04-casting","p":10,"q":"Wrought iron contains less than about ______ carbon, while cast iron contains ______ carbon.","o":["0.08%; 2.1% to 4%","2%; 6% to 6.7%","0.5%; 1% to 1.8%","0.005%; 0.06% to 2%"],"h":"Wrought iron is nearly pure iron with slag.","a":0,"id":213},{"d":"wk04-casting","p":10,"q":"The wood-like \"grain\" visible in wrought iron when etched or bent is due to:","o":["Fibrous slag inclusions","Graphite flakes","Spheroidal carbon nodules","Columnar dendrites"],"h":"Up to 2% by weight of slag.","a":0,"id":214},{"d":"wk04-casting","p":12,"q":"Cast irons are often melted in a:","o":["Blast furnace","Cupola","Electric arc crucible only","Kiln"],"h":"A continuous melter with alternating layers of coke.","a":1,"id":215},{"d":"wk04-casting","p":13,"q":"In a cupola furnace, charges of metal are melted in layers alternating with layers of fuel, usually:","o":["Charcoal","Coke","Natural gas","Wood"],"h":"Derived from coal.","a":1,"id":216},{"d":"wk04-casting","p":17,"q":"In sand casting, the cavity in the sand is formed using a(n):","o":["Pattern","Core","Riser","Sprue"],"h":"It is removed before pouring.","a":0,"id":217},{"d":"wk04-casting","p":17,"q":"In a sand casting mould, the box housing the aggregate is the:","o":["Cope","Drag","Flask","Core print"],"h":"It holds the sand.","a":2,"id":218},{"d":"wk04-casting","p":17,"q":"A sand shape inserted into the mould to produce internal features such as holes is a:","o":["Riser","Core","Pattern","Gate"],"h":"Internal passages.","a":1,"id":219},{"d":"wk04-casting","p":17,"q":"The region added to the pattern to locate and support the core within the mould is the:","o":["Riser","Runner","Core print","Parting line"],"h":"It holds the core in place.","a":2,"id":220},{"d":"wk04-casting","p":17,"q":"The purpose of a riser in sand casting is to:","o":["Feed metal to the casting as it shrinks","Form internal holes, passages and cavities","Locate and support the core","Separate the cope from the drag at the parting line"],"h":"A reservoir of extra molten metal.","a":0,"id":221},{"d":"wk04-casting","p":18,"q":"In a two-part sand mould, the upper half is the ______ and the lower half is the ______.","o":["cope; drag","drag; cope","flask; core","riser; sprue"],"h":"\"Cope\" sits on top.","a":0,"id":222},{"d":"wk04-casting","p":18,"q":"The minimum draft angle usually applied to vertical surfaces of a sand casting pattern is:","o":["0°","1°","5°","10°"],"h":"It lets the pattern be removed without breaking the mould.","a":1,"id":223},{"d":"wk04-casting","p":18,"q":"Draft on a pattern is:","o":["A slight taper on vertical faces for removal","A channel that carries metal into the cavity","Extra metal added to allow for shrinkage","The line separating the cope and the drag"],"h":"Usually at least 1°.","a":0,"id":224},{"d":"wk04-casting","p":19,"q":"There are how many major types of cast iron?","o":["3","5","7","9"],"h":"Gray iron is the oldest.","a":1,"id":225},{"d":"wk04-casting","p":21,"q":"The outstanding property of gray iron is its:","o":["Self-lubricating wear behaviour","High impact and shock strength","High ductility and elongation","Excellent weldability"],"h":"Graphite flakes help it.","a":0,"id":226},{"d":"wk04-casting","p":21,"q":"Gray irons should be considered for machine parts that do NOT involve:","o":["Shock loads, bending or high stress","Good machinability requirements","Vibration damping requirements in machine bases","Metal-to-metal sliding wear"],"h":"It is brittle.","a":0,"id":227},{"d":"wk04-casting","p":23,"q":"Which cast iron is best suited for gears, cams and machine frames that may get an occasional shock load?","o":["Ductile (nodular) iron","Gray (flake graphite) iron","White iron","Wrought iron"],"h":"It has as-cast strength higher than many mild steels.","a":0,"id":228},{"d":"wk04-casting","p":25,"q":"If many units are to be made, which cast alloy provides the best combination of machinability and stability?","o":["Gray iron","White iron","Malleable iron","Steel casting"],"h":"It is a special casting material for quantity parts.","a":2,"id":229},{"d":"wk04-casting","p":26,"q":"White iron is mainly used for:","o":["Abrasion resistance, e.g. hard rolls","Self-lubricating sliding bearings","Gears subject to shock loading","Thin decorative ornamental castings"],"h":"A specialty wear material.","a":0,"id":230},{"d":"wk04-casting","p":27,"q":"Steel castings are used:","o":["Only once a cast iron is ruled out for a tough job","As the first choice for most cast components, ahead of cast iron","Mainly for decorative and architectural items","Only for small, thin-walled parts made by die casting"],"h":"Cast irons are cheaper and easier to cast.","a":0,"id":231},{"d":"wk04-casting","p":30,"q":"During solidification, grains usually grow in a treelike form called a:","o":["Nucleus","Dendrite","Lattice","Spheroid"],"h":"From the Greek for tree.","a":1,"id":232},{"d":"wk04-casting","p":30,"q":"Which of the following is NOT one of the three major things that happen when a casting solidifies?","o":["Grains are formed","Melt chemistry changes during freezing","Shrinkage occurs","The metal is work hardened"],"h":"Work hardening comes from cold deformation.","a":3,"id":233},{"d":"wk04-casting","p":32,"q":"Turbine blades are directionally solidified in order to obtain:","o":["Columnar grains along the blade","Fine, uniform equiaxed grains","An amorphous, grain-free structure","Graphite nodules for damping"],"h":"Usually columnar grains are undesirable, but not here.","a":0,"id":234},{"d":"wk04-casting","p":33,"q":"The major sources of casting defects are:","o":["Porosity and shrinkage","Weld lines and residual stress","Springback and wrinkling","Flash and short shots"],"h":"Gas bubbles and voids.","a":0,"id":235},{"d":"wk04-casting","p":34,"q":"To minimise solidification shrinkage voids, the casting should be designed so that:","o":["Gates and risers solidify last","The thickest section solidifies first","No risers are needed at all","All sections solidify at once"],"h":"Feed metal must stay liquid longest.","a":0,"id":236},{"d":"wk04-casting","p":35,"q":"In casting design, feed paths should be:","o":["As uniform in section as possible","As varied in section as possible","As long and narrow as possible","Placed only at the thinnest walls"],"h":"Quality is built in at the design phase.","a":0,"id":237},{"d":"wk04-casting","p":39,"q":"Which casting process spins the mould, typically to produce cylindrical parts like cast-iron pipes?","o":["Investment casting","Centrifugal casting","Die casting","Shell moulding"],"h":"Centrifugal force pushes metal to the walls.","a":1,"id":238},{"d":"wk04-casting","p":41,"q":"Investment casting is also called:","o":["Lost wax or precision casting","Shell or resin-bonded moulding","Permanent or gravity mould casting","Slush or hollow mould casting"],"h":"The wax pattern is melted out.","a":0,"id":239},{"d":"wk04-casting","p":42,"q":"The plaster investment mould is typically composed of:","o":["70-80% gypsum plus fibrous strengthener","100% silica sand bonded with clay","Graphite and clay with a resin binder","Steel and bronze powders sintered together"],"h":"Plaster of Paris is gypsum.","a":0,"id":240},{"d":"wk04-casting","p":43,"q":"In investment casting, the cavity is formed when:","o":["The flask is heated and the wax melts out","A wooden pattern is drawn out of the sand","The plaster is machined to shape by CNC","A sand core is shaken out after pouring"],"h":"The pattern is lost.","a":0,"id":241},{"d":"wk04-casting","p":43,"q":"Arrange the first steps of investment casting in order:","o":["Wax part, attach sprue, pour investment, melt wax","Pour metal, make wax part, melt wax, break mould","Pour investment, make wax, attach sprue, pour metal","Make sand mould, insert wax, pour metal, melt wax"],"h":"The wax comes first.","a":0,"id":242},{"d":"wk04-casting","p":49,"q":"Which of the following is an advantage of investment casting?","o":["Fine surface and thin, intricate sections","Unlimited part size and weight","Lowest cost per part for very large, heavy castings","Fastest cycle time of any casting"],"h":"Used for jewellery and medical instruments.","a":0,"id":243},{"d":"wk04-casting","p":49,"q":"The main disadvantage of investment casting is that it is:","o":["Rough in surface finish","Limited in size","Limited to plastics","Requiring large draft angles"],"h":"Seldom exceeds about 13 kg.","a":1,"id":244},{"d":"wk04-casting","p":47,"q":"Which process is described as similar to investment moulding and uses a resin-bonded shell?","o":["Sand casting","Shell moulding","Die casting","Centrifugal casting"],"h":"A typical part is an automobile camshaft.","a":1,"id":245},{"d":"wk04-casting","p":50,"q":"Permanent moulds are often made from gray cast iron because it has:","o":["The lowest cost of all metals","About the best thermal fatigue resistance","The highest melting point","Self-lubricating properties for ejection"],"h":"Moulds are heated and cooled repeatedly.","a":1,"id":246},{"d":"wk04-casting","p":50,"q":"Permanent mould castings are limited mainly to:","o":["Aluminium, zinc, brass, bronze and lead","Steel, cast iron, stainless steel and tool steel","Tungsten, molybdenum and tantalum","Titanium, cobalt and nickel-based superalloys"],"h":"Low-melt-temperature nonferrous metals.","a":0,"id":247},{"d":"wk04-casting","p":50,"q":"Permanent moulds are usually coated with a ______ before being gravity filled.","o":["Zinc layer","Ceramic wash","Wax film","Oil"],"h":"Protects the mould from the molten metal.","a":1,"id":248},{"d":"wk04-casting","p":55,"q":"Die casting machines are classified as:","o":["Hot chamber and cold chamber","Gravity fed and pressure fed","Open and closed die","Single action and double action"],"h":"Depends on where the metal is held.","a":0,"id":249},{"d":"wk04-casting","p":57,"q":"Die casting is limited mainly to:","o":["Nonferrous metals and smaller parts","Ferrous metals and very large parts","Ceramics and glass-ceramic parts","Thermosets and filled composites"],"h":"Steel dies cannot withstand molten iron temperatures.","a":0,"id":250},{"d":"wk04-casting","p":57,"q":"Which is a disadvantage of die casting?","o":["Costly tools, long lead time, draft needed","Rough surface finish that always needs machining","Low production rates and long cycles","Only thick-walled parts can be made with this process"],"h":"Hardware is expensive.","a":0,"id":251},{"d":"wk04-casting","p":57,"q":"Typical applications of die casting include:","o":["Electronics frames, auto parts, motor housings","Large cast-iron water and sewer pipes for municipal mains","Jewellery, sculpture and dental crowns","Ship propellers and pump housings weighing over 10 tons"],"h":"High volume nonferrous parts.","a":0,"id":252},{"d":"wk04-casting","p":52,"q":"The Herman Miller Equa chair by Chadwick and Stumpf is cited as an example of a product using several:","o":["Investment castings","Metal die castings","Sand castings","Forgings"],"h":"Aluminium components for furniture.","a":1,"id":253},{"d":"wk04-casting","p":58,"q":"Which of the following is NOT one of the six factors for evaluating a casting process?","o":["Colour of the alloy","Tolerance achievable","Surface finish quality","Size and weight limitations"],"h":"The others are materials, cost and availability.","a":0,"id":254},{"d":"wk04-casting","p":61,"q":"Shrinkage allowances for sand-cast metals range from about:","o":["0.1% to 0.5%","1% to 5%","10% to 15%","20% to 30%"],"h":"It depends on the alloy.","a":1,"id":255},{"d":"wk04-casting","p":62,"q":"Which casting process has the largest tolerances?","o":["Sand casting","Investment casting","Die casting","Permanent mould casting"],"h":"The least precise.","a":0,"id":256},{"d":"wk04-casting","p":62,"q":"Which casting process has the lowest tolerances of any casting process?","o":["Sand casting","Investment casting","Die casting","Centrifugal casting"],"h":"Unfortunately limited to nonferrous metals.","a":2,"id":257},{"d":"wk04-casting","p":62,"q":"Of the processes applicable to both ferrous and nonferrous metals, which has the lowest tolerances?","o":["Sand casting","Investment casting","Die casting","Centrifugal casting"],"h":"Die casting is nonferrous only.","a":1,"id":258},{"d":"wk04-casting","p":64,"q":"Which castings are very seldom good enough to allow attachment of other parts with a respectable fit?","o":["Die castings","Investment castings","Sand castings","Shell moulded castings"],"h":"Roughest surface.","a":2,"id":259},{"d":"wk04-casting","p":65,"q":"Die casting can produce parts weighing up to about:","o":["1 kg","18 kg","100 kg","No limit"],"h":"Investment castings seldom exceed 13 kg.","a":1,"id":260},{"d":"wk04-casting","p":65,"q":"Which casting process has no real limit to size?","o":["Die casting","Investment casting","Sand casting","Shell moulding"],"h":"From small items to 150-ton machines.","a":2,"id":261},{"d":"wk04-casting","p":65,"q":"Cast-iron pipes are usually produced by:","o":["Sand casting","Centrifugal casting","Die casting","Investment casting"],"h":"Lengths of 6 m and diameters up to 600 mm.","a":1,"id":262},{"d":"wk04-casting","p":66,"q":"Tungsten and molybdenum cause casting problems because of their:","o":["High melting points","Low density","High ductility","Magnetic behaviour"],"h":"They melt above 2600°C.","a":0,"id":263},{"d":"wk04-casting","p":66,"q":"Die casting is seldom used for ferrous metals because:","o":["Steel dies cannot withstand molten ferrous temperatures","Molten ferrous metals are too fluid to fill thin sections","Ferrous metals do not shrink, so parts stick in the die","The process gives too smooth a finish for paint to adhere"],"h":"Expensive refractory moulds would be needed.","a":0,"id":264},{"d":"wk04-casting","p":69,"q":"If only a few castings are required, the cheapest process may be:","o":["Sand casting","Die casting","Permanent mould casting","Hot chamber die casting"],"h":"Low tooling cost.","a":0,"id":265},{"d":"wk04-casting","p":69,"q":"Investment casting tooling costs can often be amortised on as few as:","o":["5 castings","50 castings","5,000 castings","100,000 castings"],"h":"Castings are often ganged in one pour.","a":1,"id":266},{"d":"wk04-casting","p":69,"q":"Die casting is by far the fastest casting process, with cycle times as short as:","o":["10 seconds","1 minute","10 minutes","1 hour"],"h":"It needs thousands of parts to cover tooling cost.","a":0,"id":267},{"d":"wk04-casting","p":70,"q":"Typical lead times before the first part: sand casting ____, investment casting ____, die casting ____.","o":["1 month; 3 months; 6 months","1 week; 1 month; 3 months","3 months; 1 month; 6 months","6 months; 3 months; 1 month"],"h":"Die casting hardware takes longest.","a":0,"id":268},{"d":"wk04-casting","p":73,"q":"Ultimately, what should determine the choice between a casting or a fabrication (weldment or 3D print)?","o":["Personal preference only","Economics","Colour","Weight alone"],"h":"Cost comparisons from quotations.","a":1,"id":269},{"d":"wk04-casting","p":4,"q":"What is the primary production process for this fire hydrant?","o":["Forging","Casting","Machining from a block of steel","Sintering from powdered metal"],"h":"A complex, hollow iron shape is most economically made by pouring metal into a mould.","i":"img/hydrant.jpg","a":1,"id":270},{"d":"wk05-forming","p":4,"q":"Plastic state forming is a forming operation on solid metal at:","o":["Elevated temperature, below the melt temperature","Room temperature, well below recrystallisation","Just above the melting point of the alloy","Cryogenic temperature to prevent grain growth"],"h":"The metal is soft but not molten.","a":0,"id":271},{"d":"wk05-forming","p":4,"q":"Besides shaping the metal, the objective of plastic state forming is to:","o":["Control grain structure to enhance strength","Increase porosity to reduce part weight","Produce a random, equiaxed grain structure","Remove alloying elements from the surface"],"h":"Grain flow matters.","a":0,"id":272},{"d":"wk05-forming","p":8,"q":"When an \"S\" shaped bar is forged, its grain structure:","o":["Follows the shape, which better resists stress","Becomes random and equiaxed, as in a casting","Runs straight across, cut through by the shape","Disappears completely when the bar recrystallises"],"h":"One of the main benefits of forging.","a":0,"id":273},{"d":"wk05-forming","p":6,"q":"An S-shaped bar made by casting is weaker because:","o":["Its random grains let cracks run along boundaries","Its grain follows the shape and concentrates stress","Its surface is work hardened and becomes brittle","Its grain boundaries are removed during cooling"],"h":"Non-uniform walls also create stress concentrations.","a":0,"id":274},{"d":"wk05-forming","p":7,"q":"An S-shape cut from a rolled slab is poor in terms of stress because:","o":["The cut runs across the slab's horizontal grain","The grain flows around the curves of the shape","The grain is fully random, as in a casting","Rolling removes the grain structure entirely"],"h":"Crack potential is nearly as great as casting.","a":0,"id":275},{"d":"wk05-forming","p":12,"q":"Hammer and drop forging shape the workpiece using:","o":["Near-instantaneous impact (milliseconds)","Slow, continuous pressure over seconds","Rotating dies that hammer radially","Fluid pressure acting through a membrane"],"h":"A dropping weight.","a":0,"id":276},{"d":"wk05-forming","p":13,"q":"Press forging differs from drop forging because it:","o":["Applies slow, continuous pressure lasting seconds","Applies impact force lasting only milliseconds","Is always performed cold, below recrystallisation","Partly melts the workpiece surface in the die"],"h":"A hydraulic cylinder provides force.","a":0,"id":277},{"d":"wk05-forming","p":14,"q":"Upset forging:","o":["Increases diameter by compressing the length","Reduces diameter by hammering with rotary dies","Pulls a rod through a die to reduce its size","Forces a billet through a shaped die opening"],"h":"Used for bolt heads.","a":0,"id":278},{"d":"wk05-forming","p":14,"q":"Based on number of pieces produced, the most widely used forging process is:","o":["Drop forging","Press forging","Upset forging","Swaging"],"h":"Bolts, screws, engine valves.","a":2,"id":279},{"d":"wk05-forming","p":14,"q":"Upset forging is usually done in special high-speed machines called:","o":["Press brakes","Crank presses","Lathes","Cupolas"],"h":"A crank drives the ram.","a":1,"id":280},{"d":"wk05-forming","p":16,"q":"Swaging (rotary swaging / radial forging) uses two or more dies to:","o":["Hammer a round bar to a smaller diameter","Upset a bar end to a larger diameter for a bolt head","Bend tubes around a fixed mandrel","Spin a flat disc into a symmetrical cup shape"],"h":"Think tapered tube ends.","a":0,"id":281},{"d":"wk05-forming","p":17,"q":"During rolling, the rollers must be water-cooled because:","o":["Stress and friction generate heat","The metal must stay below 0°C","Water lubricates the grain boundaries","It prevents the rolls from corroding"],"h":"Even \"cold\" rolling gets hot.","a":0,"id":282},{"d":"wk05-forming","p":18,"q":"In hot rolling, as the grains regrow during recovery, the result is:","o":["A coarse or rough surface","A smooth, fine surface","An amorphous, grain-free structure","A mirror-like polished finish"],"h":"Compare with cold rolling.","a":0,"id":283},{"d":"wk05-forming","p":19,"q":"Cold rolling a previously hot-rolled sheet yields:","o":["A smooth, fine surface at about 20% more cost","A coarse surface at about 20% lower cost, with larger grains","A porous surface that holds paint better","No change in surface finish, grain size or overall cost"],"h":"The grains are smaller after annealing.","a":0,"id":284},{"d":"wk05-forming","p":23,"q":"In extrusion, a heated billet is:","o":["Pushed through a die by a ram","Pulled through a die by a gripper","Hammered between two shaped dies","Squeezed between a pair of rollers"],"h":"Like squeezing toothpaste.","a":0,"id":285},{"d":"wk05-forming","p":24,"q":"Extruded profiles can be:","o":["Solid, semi-hollow or hollow","Solid sections only, never hollow","Hollow tubes only","Round or square sections only"],"h":"Window frames and heat sinks.","a":0,"id":286},{"d":"wk05-forming","p":25,"q":"Extrusions have revolutionised design partly because:","o":["Most materials and dies are fairly inexpensive","They require no dies, only a shaped ram","Their cross section can vary along the length","They are used only for high-strength steels"],"h":"Virtually any profile is possible.","a":0,"id":287},{"d":"wk05-forming","p":23,"q":"The aluminium part below can be economically produced by:","o":["Investment casting","Die casting","Machining processes","Metal extrusion"],"h":"A long constant profile.","i":"img/extrusion.jpg","a":3,"id":288},{"d":"wk05-forming","p":22,"q":"In wire and rod drawing, the material is:","o":["Pulled through a die","Pushed through a die","Hammered by rotary dies","Rolled between rollers"],"h":"Relies on ductility.","a":0,"id":289},{"d":"wk05-forming","p":31,"q":"Solid state forming is the shaping of metal sheet, rod, wire or tube usually at:","o":["Above melting point","Just below critical temperature","Room temperature","Cryogenic temperature"],"h":"Heating is only sometimes required.","a":2,"id":290},{"d":"wk05-forming","p":31,"q":"A metal sheet is defined as ______ thick, while a metal plate is ______ thick.","o":["less than 6 mm; more than 6 mm","less than 1 mm; more than 1 mm","less than 12 mm; more than 12 mm","less than 3 mm; more than 25 mm"],"h":"The dividing thickness is 6 mm.","a":0,"id":291},{"d":"wk05-forming","p":32,"q":"During solid state forming, some metals can become brittle and may require ______ before forming continues.","o":["Quenching","Annealing","Galvanising","Pickling"],"h":"Softening heat treatment.","a":1,"id":292},{"d":"wk05-forming","p":33,"q":"In very high volume sheet operations with progressive, transfer or multiple-action dies that cut and form, the process is often called:","o":["Spinning","Stamping","Hydroforming","Swaging"],"h":"Also used generally for sheet forming.","a":1,"id":293},{"d":"wk05-forming","p":39,"q":"When bending tubes, an internal support called a ______ is used to prevent buckling.","o":["Core","Mandrel","Riser","Punch"],"h":"It is inserted inside the tube.","a":1,"id":294},{"d":"wk05-forming","p":40,"q":"The classic 1927 bent-tube chair that set the standard for modern furniture is the:","o":["Equa chair","Wassily chair","Barcelona chair","Panton chair"],"h":"Designed by Marcel Breuer.","a":1,"id":295},{"d":"wk05-forming","p":41,"q":"In the Wassily chair, Breuer's bending limitations became an aesthetic through:","o":["Consistent bend radii","Sharp mitred corners","Varying tube diameters","Hidden welded joints"],"h":"Tube bending has a minimum radius.","a":0,"id":296},{"d":"wk05-forming","p":45,"q":"Bending thermoplastic sheet is similar to bending sheet metal but requires:","o":["Local heating at the bend line","An internal mandrel at the bend","A matched punch and die set","Quenching in water after bending"],"h":"Strip heaters are used.","a":0,"id":297},{"d":"wk05-forming","p":47,"q":"Air bending is also known as:","o":["Three-point bending","Wipe bending","Matched V-die bending","Roll bending"],"h":"Two support points and a punch.","a":0,"id":298},{"d":"wk05-forming","p":47,"q":"Compared with V-die bending, air bending:","o":["Is cheaper but less accurate","Is more expensive and more accurate","Uses a matched punch and die","Cannot bend steel"],"h":"Eliminating the die reduces cost.","a":0,"id":299},{"d":"wk05-forming","p":48,"q":"The most expensive bending operation, using a matched punch and die designed for a particular application, is:","o":["Air bending","V-die bending","Brake bending","Roll bending"],"h":"It produces very accurate bends.","a":1,"id":300},{"d":"wk05-forming","p":49,"q":"An inexpensive bending tool often found in small model shops, with radius attachments, is the:","o":["Brake (wiping die)","Matched V-die set","Progressive die","Hydroforming press"],"h":"It wipes the sheet over an edge.","a":0,"id":301},{"d":"wk05-forming","p":51,"q":"Continuous roll forming produces profiles somewhat like extrusions, except that:","o":["Its profile is limited to the sheet's original thickness","It can only make short parts of under a metre long","It needs the metal to be molten as it enters the rolls","It can only produce fully closed hollow sections"],"h":"Sheet from a coil passes through rollers.","a":0,"id":302},{"d":"wk05-forming","p":51,"q":"A disadvantage of continuous roll forming is:","o":["Uniform thickness and large minimum orders","Uneconomical at high production volumes","Profile length limited to about one metre","Unable to form pre-coated galvanized steel"],"h":"2 m to 3000 m minimum order.","a":0,"id":303},{"d":"wk05-forming","p":53,"q":"Spinning is commonly used to produce:","o":["Symmetrical cups and discs","Long, constant-section profiles","Boxes with sharp corners","Bent wire frames"],"h":"The sheet is forced onto a pattern on a special lathe.","a":0,"id":304},{"d":"wk05-forming","p":55,"q":"Metal spinning is labour intensive but its dies (patterns) are:","o":["Very expensive","Inexpensive","Made only from ceramics","Not required"],"h":"Often wooden patterns.","a":1,"id":305},{"d":"wk05-forming","p":57,"q":"In hydroforming, a flexible membrane sealing a fluid-filled cavity:","o":["Removes the need for a matching die","Melts the surface of the workpiece","Replaces the punch entirely","Shears the sheet to its outline"],"h":"Fluid pressure acts as the female die.","a":0,"id":306},{"d":"wk05-forming","p":57,"q":"Hydroforming was developed in the late 1940s and early 1950s for:","o":["Cheaper small runs of deep drawn parts","Very high volumes of shallow stampings","Casting directionally solidified blades","Drawing fine wire from heavy rod"],"h":"Avoids an expensive matched die.","a":0,"id":307},{"d":"wk05-forming","p":59,"q":"A notable product example of hydroforming shown in the notes is:","o":["A wine bottle","A bicycle frame","A bolt","A cast-iron pipe"],"h":"Tubes expanded with fluid pressure.","a":1,"id":308},{"d":"wk05-forming","p":60,"q":"In drawing, sheet metal is formed into hollow shapes by:","o":["A punch forcing it into a matching die","Spinning it over a pattern on a lathe","Squeezing it between a series of rollers","Fluid pressure alone with no punch"],"h":"Think of a drink can.","a":0,"id":309},{"d":"wk05-forming","p":62,"q":"In deep drawing, the depth of the hollow is:","o":["Less than half the diameter","Equal to the thickness","Two or more times the diameter","Always ten times the diameter"],"h":"Normally done in successive steps.","a":2,"id":310},{"d":"wk05-forming","p":65,"q":"A simple die:","o":["Performs one action, such as bending or punching, at one time","Performs many operations at multiple stations simultaneously","Uses fluid pressure","Is used only for spinning"],"h":"The part is moved to another station afterwards.","a":0,"id":311},{"d":"wk05-forming","p":68,"q":"Which is NOT a characteristic of progressive die stamping?","o":["Multiple cutting/forming operations simultaneously","Well suited to small parts at a rapid rate","Requires expensive die sets","Ideal for very low volume prototypes"],"h":"High investment needs high volume.","a":3,"id":312},{"d":"wk05-forming","p":72,"q":"Deep draw stamping allows metal to be drawn to a ratio of about:","o":["7 or 8 to 1","1 to 1","2 or 3 to 1","20 to 1"],"h":"Progressive dies are normally limited to shallow draws.","a":0,"id":313},{"d":"wk05-forming","p":70,"q":"In progressive die stamping, the metal strip:","o":["Moves through stations, each adding to the previous form","Is spun on a lathe against a single wooden pattern until formed","Is cast into a die and ejected as a finished part","Is pushed through one die to form a long, constant cross-section profile"],"h":"The part is created in stages.","a":0,"id":314},{"d":"wk05-forming","p":31,"q":"Heating may be required in solid state forming if the metal:","o":["Is thick, low in ductility or work hardened","Is thin and needs to stay perfectly flat after forming","Is aluminium, which always needs heating","Is to be painted or powder coated later in production"],"h":"Normally done at room temperature.","a":0,"id":315},{"d":"wk06-thermoplastics","p":4,"q":"Probably the most limiting factor in applying plastics to a new design is their:","o":["Colour range","Fabricability","Density","Electrical insulation"],"h":"Whether it can actually be made into the shape.","a":1,"id":316},{"d":"wk06-thermoplastics","p":4,"q":"PTFE (Teflon) parts can only be made by:","o":["Sintering particles under pressure","Injection moulding at high melt temperature","Extrusion blow moulding of a parison","Vacuum thermoforming of heated sheet"],"h":"This plus high cost limits its use.","a":0,"id":317},{"d":"wk06-thermoplastics","p":5,"q":"Continuous fibre-reinforced plastics have higher stiffness and strength, but:","o":["Few processes can add continuous fibres cheaply","They cannot be pigmented or coloured during processing","They are weaker than the unreinforced resin","They can only be made by extrusion or calendering"],"h":"Fabrication options limit their use.","a":0,"id":318},{"d":"wk06-thermoplastics","p":7,"q":"Thermoplastic materials are those plastics that:","o":["Can be re-melted and reused","Cannot be remelted once cured","Are always crosslinked","Are only formed by casting"],"h":"Unlike thermosets.","a":0,"id":319},{"d":"wk06-thermoplastics","p":13,"q":"What are the six major steps of the injection moulding process, in order?","o":["Injection, clamping, cooling, dwelling, ejection, mould opening","Clamping, injection, dwelling, cooling, mould opening, ejection","Drying, injection, clamping, ejection, cooling, opening","Clamping, cooling, injection, dwelling, ejection, opening"],"h":"The mould must be closed first.","a":1,"id":320},{"d":"wk06-thermoplastics","p":13,"q":"In injection moulding, the \"dwelling\" step:","o":["Holds pressure to pack the cavity","Opens the mould halves for ejection","Pushes the part off the core","Dries the resin before moulding"],"h":"It comes right after injection.","a":0,"id":321},{"d":"wk06-thermoplastics","p":12,"q":"Before injection, plastic granules typically go through:","o":["Blending, drying and feeding","Sintering and pressing","Calendering and cooling","Parison extrusion and blowing"],"h":"Moisture must be removed.","a":0,"id":322},{"d":"wk06-thermoplastics","p":18,"q":"Bi-injection (two-shot) moulding is often done to:","o":["Get a cosmetic effect or change use properties","Produce hollow bottles with a moulded and threaded neck","Make large tanks with no internal core","Form thin film for food packaging and carrier bags"],"h":"e.g. a toothbrush handle with a soft grip.","a":0,"id":323},{"d":"wk06-thermoplastics","p":20,"q":"Co-injection moulding is used to achieve:","o":["A skin around a different polymer core","Two colours moulded side by side","A hollow part with a blown cavity","A foamed outer layer over a solid core"],"h":"The core can be recycled material.","a":0,"id":324},{"d":"wk06-thermoplastics","p":20,"q":"Which is a cost-saving use of co-injection?","o":["A cheap recycled core inside a premium skin","A premium core inside a cheap recycled skin","Removing the need for a closed mould","Skipping the cooling step in the cycle"],"h":"The visible skin is premium.","a":0,"id":325},{"d":"wk06-thermoplastics","p":26,"q":"Which is an advantage of injection moulding?","o":["Fast, repeatable production with little scrap","Low investment in machines and moulds, even for small runs","No design constraints on part geometry","Ideal economics for one-off parts and very short prototype runs"],"h":"Low labour costs too.","a":0,"id":326},{"d":"wk06-thermoplastics","p":26,"q":"Which is a disadvantage of injection moulding?","o":["Low production rate","High scrap losses","Expensive equipment investment","Extensive finishing required"],"h":"Moulds and machines cost a lot.","a":2,"id":327},{"d":"wk06-thermoplastics","p":27,"q":"A variation of injection moulding that produces parts with a foamed core and solid skin is:","o":["Structural foam moulding","Rotational moulding","Reaction calendering","Twin-sheet thermoforming"],"h":"Used for thick, rigid lightweight parts.","a":0,"id":328},{"d":"wk06-thermoplastics","p":30,"q":"Plastic bottles such as shampoo bottles with a handle are commonly made by:","o":["Extrusion blow moulding","Two-shot injection moulding","Rotational moulding","Calendering"],"h":"A parison is extruded and inflated.","a":0,"id":329},{"d":"wk06-thermoplastics","p":35,"q":"In blow moulding, compressed air is blown into a(n) ______ so that it takes the shape of the mould walls.","o":["Billet","Parison","Preform sheet","Calendered film"],"h":"A hollow tube of molten plastic.","a":1,"id":330},{"d":"wk06-thermoplastics","p":32,"q":"Stretch blow moulding is noted for:","o":["High quality, fully finished parts with no flash","Suitability for low-volume production of prototypes only","Making very large water and fuel tanks","Producing flat sheet and film products for packaging"],"h":"Used for PET soft drink bottles.","a":0,"id":331},{"d":"wk06-thermoplastics","p":36,"q":"Two-litre soft drink bottles are typically made from which lightweight, transparent, shatter-resistant plastic?","o":["PET","PVC","Polystyrene","ABS"],"h":"Coatings can extend shelf life.","a":0,"id":332},{"d":"wk06-thermoplastics","p":37,"q":"Calendering forms sheet or film by:","o":["Passing it through heated rolls","Forcing melt through a shaped die","Spinning a mould inside an oven","Vacuum drawing it over a mould"],"h":"Used for vinyl flooring tiles.","a":0,"id":333},{"d":"wk06-thermoplastics","p":37,"q":"Which products are often formed by calendering?","o":["Gaskets and vinyl floor tiles","Fuel tanks, water tanks and boat hulls","Shampoo and drink bottles","Door bell casings and appliance housings"],"h":"Flat sheet products.","a":0,"id":334},{"d":"wk06-thermoplastics","p":40,"q":"Calendering of film is preferably used for:","o":["Long production runs","Short production runs","One-off prototypes","Hollow moulded parts"],"h":"Precision thin sheet production.","a":0,"id":335},{"d":"wk06-thermoplastics","p":41,"q":"In the tubular film process (film blowing), after melting and cooling, further heating is used for:","o":["Axial stretching","Crosslinking","Adding a co-injected core","Calendering"],"h":"Plastic bags are made this way.","a":0,"id":336},{"d":"wk06-thermoplastics","p":43,"q":"Rotational moulding is usually used for:","o":["Large hollow tanks and boat hulls","Small precision gears and bushes","Thin packaging films and bags","Bottles produced at very high speed"],"h":"The mould rotates in an oven.","a":0,"id":337},{"d":"wk06-thermoplastics","p":43,"q":"Rotational moulding tooling is less expensive because:","o":["There is no core and no high pressure","The moulds are made from cardboard","It uses only cold-curing thermosets","The mould never needs to be heated"],"h":"Parts form by heat and rotation, not pressure.","a":0,"id":338},{"d":"wk06-thermoplastics","p":44,"q":"In rotational moulding, material is pushed to the cavity walls by:","o":["Centrifugal force","Compressed air","A moving plunger","Vacuum suction"],"h":"Then cooled for final setting.","a":0,"id":339},{"d":"wk06-thermoplastics","p":49,"q":"Solid-phase forming heats a thermoplastic sheet or preform to:","o":["Its softening point, below melting","Just above its crystalline melting point","Room temperature only","Its decomposition temperature"],"h":"It stays solid but pliable.","a":0,"id":340},{"d":"wk06-thermoplastics","p":55,"q":"Thermo vacuum forming draws a heated sheet into the shape of the mould using:","o":["Compressed air from inside","Heat and negative pressure (vacuum)","A matched metal die at high pressure","Centrifugal force"],"h":"Low tooling costs.","a":1,"id":341},{"d":"wk06-thermoplastics","p":55,"q":"Which is an advantage of vacuum forming?","o":["Cheap tooling and quick startup for small runs","Best suited to very thick, solid sections","Produces closed hollow containers in one step","Gives the tightest tolerances of any process"],"h":"Good for prototyping.","a":0,"id":342},{"d":"wk06-thermoplastics","p":58,"q":"Plastic extrusion forms continuous shapes by:","o":["Forcing melt through a die","Passing sheet through rolls","Blowing a hot parison","Sintering powder under heat"],"h":"Used for weather stripping.","a":0,"id":343},{"d":"wk06-thermoplastics","p":58,"q":"Specially shaped weather stripping is typically made by:","o":["Injection moulding","Extrusion","Rotational moulding","Thermoforming"],"h":"Continuous constant profile.","a":1,"id":344},{"d":"wk06-thermoplastics","p":61,"q":"3D printing builds physical objects from digital models by:","o":["Adding material layer by layer","Removing material by cutting","Forcing material through a die","Spinning material in a mould"],"h":"Additive manufacturing.","a":0,"id":345},{"d":"wk06-thermoplastics","p":63,"q":"An injection moulding, blow moulding or film blowing machine can easily cost more than:","o":["$1,000","$10,000","$100,000","$10,000,000"],"h":"High equipment cost is why vendors specialise.","a":2,"id":346},{"d":"wk06-thermoplastics","p":63,"q":"Which thermoplastic process can be done with very simple equipment like wooden forms, a vacuum cleaner and an oven?","o":["Injection moulding","Blow moulding","Thermoforming","Calendering"],"h":"Heat a sheet and suck it down.","a":2,"id":347},{"d":"wk06-thermoplastics","p":9,"q":"A door bell casing made from ABS would most likely be produced by:","o":["Blow moulding","Injection moulding","Calendering","Rotational moulding"],"h":"A small, detailed, high-volume part.","a":1,"id":348},{"d":"wk06-thermoplastics","p":6,"q":"When selecting a plastic, which fabrication question is relevant?","o":["What is its moulding shrinkage?","Is it ferromagnetic?","What is its Mohs hardness?","Can it be galvanised or anodised?"],"h":"Consider fabrication options with the plastic.","a":0,"id":349},{"d":"wk07-thermosets","p":4,"q":"The first completely man-made thermosetting plastic, discovered by Leo Baekeland in 1907, is:","o":["Phenol formaldehyde","Urea formaldehyde","Unsaturated polyester","Melamine formaldehyde"],"h":"Trade name Bakelite.","a":0,"id":350},{"d":"wk07-thermosets","p":4,"q":"True Bakelite (phenolic) mouldings are limited to:","o":["Black and dark colours","Bright colours and white","Transparent grades only","Pale pastel colours"],"h":"Urea formaldehyde later allowed brighter colours.","a":0,"id":351},{"d":"wk07-thermosets","p":5,"q":"The GPO Telephone No.162 (1935) was notable as the first:","o":["All-plastic phone, in phenolic","Injection moulded ABS phone","Rotationally moulded product","Cordless phone with plastic case"],"h":"An iconic Bakelite product.","a":0,"id":352},{"d":"wk07-thermosets","p":6,"q":"Urea formaldehyde, developed by British Cyanides in 1925, improved on phenolic by allowing:","o":["Bright colours and decorative patterns","Higher heat resistance than phenolic","Remelting and reuse of scrap mouldings","Fully transparent mouldings"],"h":"Bakelite was restricted to dark colours.","a":0,"id":353},{"d":"wk07-thermosets","p":9,"q":"Liquid thermoset resin systems such as epoxy require:","o":["Mixing resin and hardener to start crosslinking","Cooling below Tg so the liquid resin solidifies","Remelting the cured resin in a heated extruder","Sintering resin powder under heat and pressure"],"h":"e.g. a bisphenol A resin plus a polyamide hardener.","a":0,"id":354},{"d":"wk07-thermosets","p":12,"q":"Why are thermosets often moulded in simpler equipment than thermoplastics?","o":["They can't be remelted, so cleanout is hard","They need much higher injection pressures","They are always liquid, so need no barrel","They can't be heated without decomposing"],"h":"A thermoset curing in a barrel can fuse the screw in place.","a":0,"id":355},{"d":"wk07-thermosets","p":14,"q":"In compression moulding, the preheated, premeasured material is:","o":["Placed in an open mould, which is closed under heat and pressure","Injected through a gate into a closed, heated mould under pressure","Poured into an open mould with no pressure and left to cure","Sprayed onto an open mould in layers with chopped fibres"],"h":"Like making a waffle.","a":0,"id":356},{"d":"wk07-thermosets","p":16,"q":"The most widely used process for thermosetting materials is:","o":["Injection moulding","Compression moulding","Blow moulding","Calendering"],"h":"Cycle times are longer than injection moulding.","a":1,"id":357},{"d":"wk07-thermosets","p":16,"q":"Compression moulding cycle times for thermosets are much longer than injection moulding because:","o":["The moulds are larger","Curing of thermosets is a time-dependent reaction","The material must be cooled to room temperature","The press is slower"],"h":"Crosslinking takes time.","a":1,"id":358},{"d":"wk07-thermosets","p":17,"q":"Thermoset injection moulding cycles are how much faster than compression moulding?","o":["2 to 3 times faster","The same","10 to 20 times faster","Slower"],"h":"Yielding lower cost parts.","a":0,"id":359},{"d":"wk07-thermosets","p":18,"q":"In thermoset injection moulding, the polymer is injected when:","o":["At its lowest viscosity","Once fully crosslinked","While completely cold","As a solid pellet"],"h":"Viscosity then increases as it cross-links in the mould.","a":0,"id":360},{"d":"wk07-thermosets","p":18,"q":"After ejection in thermoset injection moulding, parts may be:","o":["Post-cured in an oven","Remelted and reground","Quenched in cold water","Vulcanised with sulfur"],"h":"An off-line step.","a":0,"id":361},{"d":"wk07-thermosets","p":19,"q":"Thermoset injection moulding is characterised by:","o":["Low part cost, high tool cost","High part cost, low tool cost","Low production rate, low cost","Unstable materials, high scrap"],"h":"High volume process.","a":0,"id":362},{"d":"wk07-thermosets","p":21,"q":"The advantage of foam moulding is the ability to:","o":["Add section size and stiffness with little extra material","Make clear parts that are fully transparent for display uses","Eliminate the need for any mould tooling","Produce very thin, flexible packaging film at high output rates"],"h":"Also less shrinkage and better tolerances.","a":0,"id":363},{"d":"wk07-thermosets","p":22,"q":"The most common thermoset foams, used for furniture, bedding and auto seats, are:","o":["Polyurethanes","Polystyrene foams","Phenolic foams","Silicone foams"],"h":"PU foam.","a":0,"id":364},{"d":"wk07-thermosets","p":23,"q":"Reaction injection moulding (RIM) is most commonly used with:","o":["Polyurethane foams","PTFE fluoropolymers","Molten glass","Phenolic (Bakelite)"],"h":"Polymer reactants are mixed under high pressure.","a":0,"id":365},{"d":"wk07-thermosets","p":23,"q":"RIM cycle times are usually:","o":["Under two minutes","Over 30 minutes","About 10 seconds","Several hours"],"h":"Fast for large parts.","a":0,"id":366},{"d":"wk07-thermosets","p":26,"q":"Transfer moulding is a modification of compression moulding in which:","o":["Material is heated in a pot and forced into the cavity","Resin is sprayed into the open mould together with chopped fibres","No heat is used at any stage of the cycle","The mould is rotated slowly in an oven until the material coats it"],"h":"The material is transferred from a pot.","a":0,"id":367},{"d":"wk07-thermosets","p":28,"q":"Resin transfer moulding (RTM) process characteristics include:","o":["Low tooling cost, low rate, strong parts","High rate, high tooling cost, weak parts","Low part strength but very fast cycles","Parts that cannot be painted or coated"],"h":"Good for low-volume strong parts.","a":0,"id":368},{"d":"wk07-thermosets","p":29,"q":"Polymer casting forms shapes by:","o":["Pouring liquid into a mould without pressure","Injecting melt into a mould at high pressure","Forcing it continuously through a shaped die","Compressing dry powder in a heated die"],"h":"Used for urethane and silicone elastomers.","a":0,"id":369},{"d":"wk07-thermosets","p":31,"q":"Rotational casting of thermosets differs from rotational moulding of thermoplastics because:","o":["The mould need not be heated","It needs much higher pressure","It uses no mould at all","It rotates on only one axis"],"h":"Liquid reactants cure on their own.","a":0,"id":370},{"d":"wk07-thermosets","p":32,"q":"Sintering of high-temperature polymers such as fluorocarbons and polyimides involves:","o":["Compressing and heating particles until they coalesce","Melting the polymer fully so it flows into the mould","Mixing a resin and hardener so they crosslink","Vulcanising the particles together with sulfur"],"h":"The particles do not melt and flow.","a":0,"id":371},{"d":"wk07-thermosets","p":33,"q":"Vulcanisation of rubber is a chemical process in which:","o":["Molecules are linked by atomic bridges, hardening the rubber","Rubber is melted down and reformed into new products for recycling","Rubber is foamed with a blowing agent to lighten it","Plasticisers are added to make the rubber softer and more flexible"],"h":"It is irreversible.","a":0,"id":372},{"d":"wk07-thermosets","p":35,"q":"The chemical crosslinking in vulcanisation is usually done with:","o":["Chlorine","Sulfur","Carbon dioxide","Nitrogen"],"h":"Popularised by Charles Goodyear.","a":1,"id":373},{"d":"wk07-thermosets","p":34,"q":"Uncured natural rubber perishes partly because:","o":["Its proteins break down and its molecules oxidise","It crystallises slowly at room temperature until it cracks apart","It absorbs too much sulfur from the air","It hardens because its crosslinks multiply in storage over time"],"h":"Sunlight accelerates it.","a":0,"id":374},{"d":"wk07-thermosets","p":33,"q":"Vulcanisation changes the surface of rubber from:","o":["Sticky to smooth and non-adhering","Smooth to sticky and tacky to the touch","Hard and glassy to liquid","Transparent to opaque only, with no change in feel"],"h":"Before vulcanisation, rubber is sticky.","a":0,"id":375},{"d":"wk07-thermosets","p":39,"q":"When thermosets are overheated, they:","o":["Char, but are often still usable","Melt and flow like a thermoplastic","Turn clear and glassy","Revert to uncured liquid resin"],"h":"They do not melt.","a":0,"id":376},{"d":"wk07-thermosets","p":40,"q":"Some thermoplastics have higher use temperatures than thermosets, but they have little strength above about:","o":["60°C","120°C","260°C","1000°C"],"h":"And they melt when overheated.","a":2,"id":377},{"d":"wk07-thermosets","p":44,"q":"Polymer composite matrices are mostly made from:","o":["Epoxy, polyester and other thermosets","Glass, graphite, aramid and boron fibres","Aluminium, magnesium and steel","Paper, cotton, wood flour and other cellulose fillers"],"h":"The reinforcements are glass, graphite, aramid etc.","a":0,"id":378},{"d":"wk07-thermosets","p":46,"q":"Wood is a natural composite in which ______ fibres provide reinforcement.","o":["Glass","Lignin-free carbon","Cellulose","Keratin"],"h":"Plant fibres.","a":2,"id":379},{"d":"wk07-thermosets","p":51,"q":"About what percentage of the Airbus A350's primary structure is carbon-fibre-reinforced polymer?","o":["19%","35%","53%","80%"],"h":"The highest of major commercial airliners.","a":2,"id":380},{"d":"wk07-thermosets","p":52,"q":"Compared with discontinuous (chopped) reinforcements, continuous reinforcements:","o":["Spread loads through the part, better for creep","Are used only in thermoplastic matrices such as nylon","Give lower strength than chopped fibres","Improve only short-term properties, not creep or fatigue"],"h":"They offer the most potential to compete with metals.","a":0,"id":381},{"d":"wk07-thermosets","p":52,"q":"Polymer composites are replacing metals on automobiles mainly because of:","o":["Lower weight and corrosion resistance","Higher cost and better conductivity","Higher density and stiffness","Better weldability and repairability"],"h":"Lower strength, less costly composites.","a":0,"id":382},{"d":"wk07-thermosets","p":53,"q":"Thermoplastic matrices were primarily reinforced with:","o":["Chopped glass in moulding pellets","Continuous carbon fibre tows laid in a mould","Woven aramid fabric layers","Aluminium honeycomb cores bonded between skins"],"h":"Injection moulded glass-filled nylon.","a":0,"id":383},{"d":"wk07-thermosets","p":54,"q":"The most important thermosetting matrix resins are:","o":["Phenolics, epoxies and polyesters","PVC, polyethylene and polypropylene","Nylon, acetal and PET","Silicones and natural rubbers"],"h":"Three thermoset families.","a":0,"id":384},{"d":"wk07-thermosets","p":55,"q":"A major application of phenolic composites is:","o":["Boat hulls","Circuit boards","Fuel tanks","Bicycle frames"],"h":"Good electrical insulation and high modulus.","a":1,"id":385},{"d":"wk07-thermosets","p":57,"q":"Formica decorative laminates for kitchen counters use which resin?","o":["Phenolic","Epoxy","Unsaturated polyester","Polyurethane"],"h":"Layers of paper compression laminated.","a":0,"id":386},{"d":"wk07-thermosets","p":58,"q":"Particle boards widely used in furniture use which resin?","o":["Urea formaldehyde","Two-part epoxy","Unsaturated polyester","PTFE"],"h":"Similar to phenolic.","a":0,"id":387},{"d":"wk07-thermosets","p":59,"q":"A unique characteristic of epoxies is:","o":["Almost no size change on curing and no emissions","High shrinkage on curing that needs allowance","The ability to be remelted and reshaped","A need for sulfur to start the curing reaction"],"h":"The catalyst becomes part of the structure.","a":0,"id":388},{"d":"wk07-thermosets","p":60,"q":"Epoxy shrink rates can be as low as:","o":["0.01%","1%","5%","10%"],"h":"Low shrinkage tendency.","a":0,"id":389},{"d":"wk07-thermosets","p":60,"q":"Epoxy resins are probably the most important matrix for high-performance composites due to:","o":["High strength and low shrinkage","The lowest cost of any resin","High shrinkage for easy demoulding","Ease of remelting and reuse"],"h":"Two-component systems.","a":0,"id":390},{"d":"wk07-thermosets","p":61,"q":"By far the most important resins for general-purpose composites, e.g. fibreglass boats and the Corvette, are:","o":["Unsaturated polyesters","Epoxies","Phenolics","Polyimides and bismaleimides"],"h":"Much lower in cost than epoxies.","a":0,"id":391},{"d":"wk07-thermosets","p":61,"q":"Compared to epoxies, unsaturated polyesters are:","o":["Cheaper and slightly weaker","Costlier and stronger","Thermoplastics, not thermosets","Used only with carbon fibre"],"h":"General-purpose.","a":0,"id":392},{"d":"wk07-thermosets","p":62,"q":"The smooth, pigmented outer skin on fibreglass boats is called the:","o":["Mat","Gel coat","Roving","Prepreg"],"h":"Made from UP with fillers.","a":1,"id":393},{"d":"wk07-thermosets","p":62,"q":"Pipe and structural composite shapes are typically made by:","o":["Hand lay-up","Spray-up","Pultrusion","Vacuum bagging"],"h":"Fibre and resin are pulled through a die.","a":2,"id":394},{"d":"wk07-thermosets","p":65,"q":"The biggest advantages of paper and cotton reinforcements are:","o":["Low cost and ease of machining","Highest strength and stiffness","Lowest weight","Transparency"],"h":"Hard reinforcements cause tool wear.","a":0,"id":395},{"d":"wk07-thermosets","p":66,"q":"Beehive-pattern aluminium honeycomb panels are important in:","o":["Aircraft","Plumbing","Food packaging","Circuit boards"],"h":"Extremely light for a given section modulus.","a":0,"id":396},{"d":"wk07-thermosets","p":67,"q":"European car makers are developing metal/plastic/metal laminates for hoods because they:","o":["Can be stamped and drawn like steel","Are transparent for styling effects","Cannot corrode under any conditions","Need no tooling to form their shape"],"h":"Easier and cheaper than honeycomb.","a":0,"id":397},{"d":"wk07-thermosets","p":68,"q":"Kevlar aramid fibre has a tensile strength of about:","o":["420 MPa","1000 MPa","3102 MPa","100 MPa"],"h":"Steel UTS is about 420 MPa.","a":2,"id":398},{"d":"wk07-thermosets","p":69,"q":"The main advantages of Kevlar over glass reinforcement are:","o":["Greater toughness and lighter weight","Lower cost and easier machining","Higher temperature resistance and conductivity","Transparency"],"h":"A 5 m canoe weighs only 7 kg.","a":0,"id":399},{"d":"wk07-thermosets","p":69,"q":"Nomex is a high-temperature nylon that, compared with Kevlar, is:","o":["Weaker, but easier and cheaper to process","Stronger, but harder and costlier to process","Heavier and more brittle at high temperature","Electrically conductive and used in circuits"],"h":"Used for anti-flash gear.","a":0,"id":400},{"d":"wk07-thermosets","p":70,"q":"PAN carbon fibres can have a tensile modulus in excess of:","o":["758,000 MPa","210,000 MPa","70,000 MPa","3,102 MPa"],"h":"Extremely high stiffness.","a":0,"id":401},{"d":"wk07-thermosets","p":71,"q":"Carbon fibres are used where:","o":["Glass cannot give the stiffness or weight saving","Low cost is the top priority for the part","High electrical insulation is required in the finished part","Optical transparency is needed in the part"],"h":"They are grown smaller than 0.005 mm diameter.","a":0,"id":402},{"d":"wk07-thermosets","p":72,"q":"The most common reinforcement for polymer composites is:","o":["Carbon fibre","Kevlar","Glass fibre","Cotton"],"h":"Made by flowing molten glass through tiny holes.","a":2,"id":403},{"d":"wk07-thermosets","p":72,"q":"E glass is named for:","o":["Electrical applications","Extra strength","Epoxy resin compatibility","Elastic behaviour"],"h":"S glass has higher tensile strength.","a":0,"id":404},{"d":"wk07-thermosets","p":72,"q":"S glass, compared with E glass, is a magnesia/alumina/silica glass with:","o":["Lower cost","Higher tensile strength","Better electrical insulation only","Lower melting point"],"h":"S for strength.","a":1,"id":405},{"d":"wk07-thermosets","p":73,"q":"The use of two-dimensional weaves in laminates produces:","o":["Anisotropic strength","Isotropic strength","Transparent laminates","Zero interlaminar shear"],"h":"3D weaves are an area of research.","a":0,"id":406},{"d":"wk07-thermosets","p":74,"q":"Glass fibre mats, compared with weaves:","o":["Need more resin but give a better surface","Need less resin but give a rougher surface","Use continuous rather than chopped fibres","Cannot be used with polyester resins"],"h":"Randomly intertwined discontinuous fibres.","a":0,"id":407},{"d":"wk07-thermosets","p":74,"q":"Bundles of glass strands formed into a large continuous strand are called:","o":["Mat","Roving","Chopped strand","Gel coat"],"h":"Heavy composites use cloths woven from it.","a":1,"id":408},{"d":"wk07-thermosets","p":77,"q":"In contact moulding (hand lay-up), the maximum composite thickness is usually about:","o":["1 mm","9 mm","50 mm","100 mm"],"h":"Layers of resin and glass are built up.","a":1,"id":409},{"d":"wk07-thermosets","p":78,"q":"Filament winding is widely used to make:","o":["Chemical pipes and tanks","Boat hulls and bathtubs","Printed circuit boards","Car dashboards and fenders"],"h":"Strands are wound around a mandrel.","a":0,"id":410},{"d":"wk07-thermosets","p":78,"q":"In filament winding, the winding pattern can be varied to:","o":["Control the strength","Change the colour","Reduce the amount of resin","Add transparency"],"h":"Extra layers in high-stress areas.","a":0,"id":411},{"d":"wk07-thermosets","p":79,"q":"Sheet moulding compound (SMC) consists of:","o":["Resin kneaded into glass to form a sheet","Chopped fibres and resin kneaded like dough","A pure resin film with no reinforcement","Woven aramid prepreg cured in an autoclave"],"h":"Cut to size and pressed in a matched mould.","a":0,"id":412},{"d":"wk07-thermosets","p":80,"q":"Bulk moulding compound (BMC) resembles:","o":["A dough of resin and chopped fibre","A thin sheet of resin rolled between films","A continuous glass roving","An aluminium honeycomb core with skins"],"h":"Used for compression moulding charges.","a":0,"id":413},{"d":"wk07-thermosets","p":81,"q":"Continuous pultrusion makes glass-reinforced shapes by:","o":["Pulling resin-wet strands through a heated die","Spraying chopped glass and resin onto a mould","Pushing a heated billet through a shaped die","Winding resin-wet strands onto a mandrel"],"h":"Pipes, channels and I-beams.","a":0,"id":414},{"d":"wk07-thermosets","p":82,"q":"Chopped fibre spraying is faster than hand lay-up, but:","o":["Chopped fibre is weaker than mat or woven lay-ups","It cannot be used to make large parts such as boat hulls","It needs a matched metal mould set","It only works with epoxy resins, not with unsaturated polyesters"],"h":"Used for shower stalls and bathtubs.","a":0,"id":415},{"d":"wk07-thermosets","p":83,"q":"Resin transfer moulding improves on contact moulding because it:","o":["Gives two finished surfaces","Needs no mould at all","Uses no liquid resin","Is limited to small parts"],"h":"A close-fitting mould is closed and resin is pumped in.","a":0,"id":416},{"d":"wk07-thermosets","p":84,"q":"Vacuum bag forming eliminates the high cost of matched metal moulds by using:","o":["Atmospheric pressure","Centrifugal force","Hydraulic rams and platens","Explosive forming"],"h":"A vacuum is pulled under a bag.","a":0,"id":417},{"d":"wk07-thermosets","p":85,"q":"High-performance polymer composites are more likely to be made from:","o":["Thermoplastic resins","Thermosetting resins","Natural rubber","Recycled PET"],"h":"Epoxy and polyester matrices.","a":1,"id":418},{"d":"wk08-cutting","p":4,"q":"In manufacturing, cutting is divided into which four subgroups?","o":["Sheet, chip forming, nonchip and thermal","Sawing, drilling, turning and milling","Punching, blanking, shearing and deburring","Laser, plasma, oxy-acetylene and EDM"],"h":"Fig: the cutting family tree.","a":0,"id":419},{"d":"wk08-cutting","p":6,"q":"In the sheet metal industry, rough-cutting or sizing sheet stock is normally referred to as:","o":["Cutting","Shearing","Machining","Broaching"],"h":"The scrap is called cut-offs or drops.","a":1,"id":420},{"d":"wk08-cutting","p":6,"q":"In the sheet metal industry, scrap from shearing is referred to as:","o":["Cut-offs or drops","Chips or swarf","Burrs or slivers","Blanks or slugs"],"h":"Leftover pieces of sheet.","a":0,"id":421},{"d":"wk08-cutting","p":7,"q":"Sheet-metal punching or shearing is limited to sheet thickness of:","o":["6 mm or less","1 mm or less","12 mm or less","25 mm or less"],"h":"The sheet/plate boundary.","a":0,"id":422},{"d":"wk08-cutting","p":9,"q":"Old dedicated punch-and-die technology is still needed for:","o":["Long runs that justify a special tool","One-off prototypes and small sample batches","Cutting plate thicker than 25 mm","Non-metallic sheet materials such as plastics only"],"h":"High volume justifies the tool.","a":0,"id":423},{"d":"wk08-cutting","p":11,"q":"Punching and blanking are almost identical except:","o":["In which piece is kept: the hole or the cut-out","In that blanking uses a laser instead of a punch","In that punching is always done on hot metal","In that blanking applies only to plastic sheet"],"h":"The difference is what you keep.","a":0,"id":424},{"d":"wk08-cutting","p":13,"q":"A turret punch:","o":["Holds many punches to make varied holes nonstop","Uses one dedicated blanking die for each part","Uses a focused laser to burn the holes","Rotates the workpiece to turn cylinders"],"h":"Rapid tool change.","a":0,"id":425},{"d":"wk08-cutting","p":15,"q":"CNC sheet metal punching centres have replaced the old method of designing a specific punch called a:","o":["Blanking die","Turret head","Broach","Mandrel"],"h":"Standard punches make many hits instead.","a":0,"id":426},{"d":"wk08-cutting","p":17,"q":"The quality of a sheared edge depends mainly on the:","o":["Clearance between punch and die","Colour and coating of the sheet","Speed of the press operator","Type of lubricant on the sheet"],"h":"Too large leads to distortion and big burrs.","a":0,"id":427},{"d":"wk08-cutting","p":18,"q":"Shearing is a tearing action that leaves a sharp residue called a(n):","o":["Chip","Burr","Kerf","Flash"],"h":"It must be removed by deburring.","a":1,"id":428},{"d":"wk08-cutting","p":19,"q":"Deburring and polishing of small metal parts is often done in a:","o":["Vibratory bowl with abrasive media","Lathe with a polishing chuck and buffing wheel","Cupola with a slag tap","Vacuum bag with peel ply and breather cloth"],"h":"Parts and media tumble together.","a":0,"id":429},{"d":"wk08-cutting","p":21,"q":"With computer controlled machining, which tolerance is now routine?","o":["1 mm","0.1 mm","0.01 mm","0.0001 mm"],"h":"In the recent past 0.1 mm was normal.","a":2,"id":430},{"d":"wk08-cutting","p":21,"q":"For high-precision machining work, tolerances of ______ or less can be achieved.","o":["0.002 mm","0.1 mm","0.05 mm","1 mm"],"h":"Very fine precision.","a":0,"id":431},{"d":"wk08-cutting","p":22,"q":"Chip-forming cutting is possible as long as:","o":["The tool is harder than the work","The work is heated beforehand","The work is a thermoplastic","The work is electrically conductive"],"h":"The cutter must win.","a":0,"id":432},{"d":"wk08-cutting","p":22,"q":"When chip-forming cutting achieves tolerances of at least 0.1 mm, it is called:","o":["Shearing","Machining","Blanking","Sawing"],"h":"A special machine drives the tool.","a":1,"id":433},{"d":"wk08-cutting","p":25,"q":"Which of the following is NOT a reason machining is difficult to analyse?","o":["Very large strain and very high strain rate","Sensitivity to tool geometry, material and temperature","Prior work hardening greatly affects the process","The process is perfectly symmetrical and constrained"],"h":"It is bounded only by the cutting tool.","a":3,"id":434},{"d":"wk08-cutting","p":26,"q":"The two basic types of sawing are:","o":["Reciprocating and circular","Band and wire","Hot and cold","Rotary and radial abrasive"],"h":"Circular includes band and disc blades.","a":0,"id":435},{"d":"wk08-cutting","p":28,"q":"The most common cutting tool for drilling, usually made from high speed tool steel, is the:","o":["Twist drill","Reamer","Broach","Ball-nose end mill"],"h":"It cuts holes along one axis.","a":0,"id":436},{"d":"wk08-cutting","p":31,"q":"A reamer is used to:","o":["Enlarge an existing hole slightly and accurately","Create a new hole in solid material without a pilot hole","Cut external threads on a turned part","Grind flat surfaces to a fine, mirror-like finish"],"h":"A finishing step for holes.","a":0,"id":437},{"d":"wk08-cutting","p":32,"q":"In turning on a lathe:","o":["The work spins while the cutter is fed along it","The cutter spins while the work is held fixed","The work reciprocates under a fixed tool","Abrasive grains on a wheel remove chips"],"h":"Produces symmetrical cylindrical shapes.","a":0,"id":438},{"d":"wk08-cutting","p":32,"q":"A lathe is best suited to produce:","o":["Cylindrical parts and threads","Flat plates with pockets and slots","Sheet metal enclosures","Deep drawn cups, cans and housings"],"h":"The workpiece spins.","a":0,"id":439},{"d":"wk08-cutting","p":39,"q":"Modern automated turning centres may be fitted with turret heads holding up to:","o":["8 tools","2 tools","100 tools","1 tool"],"h":"Turret heads change tools quickly.","a":0,"id":440},{"d":"wk08-cutting","p":41,"q":"A vertical mill looks like a drill but differs because:","o":["It has more flexible cutting axes and table movement","It cannot cut metal, only plastics, wood and other soft materials","It only cuts straight down along one axis","It rotates the workpiece rather than the cutter, like a lathe"],"h":"The head can be tilted.","a":0,"id":441},{"d":"wk08-cutting","p":43,"q":"Horizontal mills are no longer manufactured because they have been replaced by:","o":["Machining centres","Shapers","CNC lathes","Broaching machines"],"h":"CNC multi-axis machines.","a":0,"id":442},{"d":"wk08-cutting","p":47,"q":"A boring machine is used to:","o":["Finish internal bores","Drill holes from solid","Cut external threads","Flatten sheet stock"],"h":"Used to finish cannon barrels.","a":0,"id":443},{"d":"wk08-cutting","p":48,"q":"A shaper:","o":["Planes the surface with a reciprocating tool","Grinds the surface with abrasive wheels","Is a high-production, fully automated process","Spins the workpiece against a fixed tool"],"h":"Basically planing.","a":0,"id":444},{"d":"wk08-cutting","p":49,"q":"The shaping machine is particularly suited to machining flat surfaces where:","o":["Very small amounts of metal are removed very accurately","A large amount of metal has to be removed","Holes are required","Cylindrical parts are needed"],"h":"Milling is better for small, accurate removal.","a":1,"id":445},{"d":"wk08-cutting","p":50,"q":"The cutting tool in grinding is composed of:","o":["Abrasive grains bonded into a wheel","A single-point carbide cutting insert","A traveling wire charged with current","A long bar of progressively larger teeth"],"h":"Each grain removes a small chip.","a":0,"id":446},{"d":"wk08-cutting","p":51,"q":"Grinding is a finishing operation, normally for bearing or sliding surfaces, with common tolerances of:","o":["±0.005 mm","±0.5 mm","±0.1 mm","±1 mm"],"h":"Very fine.","a":0,"id":447},{"d":"wk08-cutting","p":50,"q":"Which is NOT a basic grinding operation listed?","o":["Surface grinding","Cylindrical grinding","Centreless grinding","Reciprocating grinding"],"h":"The fourth is internal grinding.","a":3,"id":448},{"d":"wk08-cutting","p":53,"q":"A broach is:","o":["A long multi-toothed tool that finishes a surface in one pass","A rotary tool used to enlarge an existing hole very slightly","A sheet metal punch that cuts many hole sizes on a turret","An abrasive wheel used for internal and centreless grinding"],"h":"e.g. keyways.","a":0,"id":449},{"d":"wk08-cutting","p":54,"q":"The high cost of a special broach can be justified only for:","o":["High-quantity production","One-off replacement parts","Plastic parts only","Prototype runs"],"h":"Expensive tooling needs volume.","a":0,"id":450},{"d":"wk08-cutting","p":55,"q":"The machining centre is now the dominant machining process because:","o":["It cuts up to 5 sides in one setup, quickly and accurately","It is the cheapest machine tool to buy and run for any production volume","It removes material without any cutting tools","It is designed mainly for cutting plastics and composite materials"],"h":"Reduces machining from days to hours.","a":0,"id":451},{"d":"wk08-cutting","p":57,"q":"A CNC turning centre program can exchange complete sets of tooling in less than:","o":["1 hour","10 minutes","30 seconds","1 second"],"h":"Formerly took one or more hours.","a":2,"id":452},{"d":"wk08-cutting","p":60,"q":"Nonchip forming cutting processes commonly achieve tolerances of:","o":["1 mm","0.5 mm","0.01 mm","0.0001 mm"],"h":"Used for electronic, scientific and defence equipment.","a":2,"id":453},{"d":"wk08-cutting","p":61,"q":"Thermal cutting processes are generally used for bulk cutting and achieve tolerances of about:","o":["0.001 mm","0.1 mm","1 mm","5 mm"],"h":"Not normally considered machining.","a":1,"id":454},{"d":"wk08-cutting","p":62,"q":"Chemical milling usually forms shallow cavities (up to about 12 mm) for:","o":["Weight reduction in aerospace parts","Decoration on consumer products only","Cutting internal and external threads","Polishing surfaces to a mirror finish"],"h":"Hard-to-cut aerospace materials.","a":0,"id":455},{"d":"wk08-cutting","p":63,"q":"In chemical milling, selective attack on the workpiece is controlled by:","o":["Masks or partial immersion","A controlled spark gap","An abrasive air jet","A focused high-power laser beam"],"h":"Low tooling cost, suited to low production.","a":0,"id":456},{"d":"wk08-cutting","p":64,"q":"Electro-chemical machining (ECM) is essentially the reverse of:","o":["Welding","Electroplating","Casting","Anodising only"],"h":"It removes metal instead of depositing it.","a":1,"id":457},{"d":"wk08-cutting","p":65,"q":"In ECM, tools are generally made of:","o":["Brass, copper or stainless steel","Carbon graphite only","Industrial diamond or cubic boron nitride","Aluminium oxide grit"],"h":"Conductive salt solution removes material.","a":0,"id":458},{"d":"wk08-cutting","p":65,"q":"ECM is suitable for:","o":["Medium to high production","Very low production only","Plastic workpieces only","Timber and wood products"],"h":"Large amounts of metal from complex cavities.","a":0,"id":459},{"d":"wk08-cutting","p":66,"q":"In electrical discharge machining (EDM), metals are eroded by:","o":["Sparks through a nonconductive fluid","Chemical etchants with masking","Abrasive particles in a gas jet","High pressure water carrying garnet abrasive"],"h":"The tool is typically carbon.","a":0,"id":460},{"d":"wk08-cutting","p":70,"q":"EDM is used extensively in producing:","o":["Injection and die-cast tooling","Blow moulded bottles","Sheet metal enclosures and brackets","Timber furniture parts"],"h":"Errors are virtually eliminated.","a":0,"id":461},{"d":"wk08-cutting","p":70,"q":"Wire EDM uses ______ as a cutter.","o":["A rotating disc","A traveling wire","A laser beam","A water jet"],"h":"A recent development of EDM.","a":1,"id":462},{"d":"wk08-cutting","p":73,"q":"In abrasive-jet machining (AJM), grit is carried by:","o":["Dry air or gas","Pure water","Light oil","An electric arc"],"h":"The nozzle is tungsten carbide or sapphire.","a":0,"id":463},{"d":"wk08-cutting","p":74,"q":"AJM can cut very thin brittle materials without breakage because:","o":["There is little impact or heat","It cuts faster than any other method","It works inside a vacuum chamber","It melts rather than fractures the material"],"h":"It is slow and needs dust collection.","a":0,"id":464},{"d":"wk08-cutting","p":75,"q":"Water-jet cutting with abrasive (HDM) fires the stream at velocities up to:","o":["30 m/s","300 m/s","1030 m/s","10,000 m/s"],"h":"About 3400 fps.","a":2,"id":465},{"d":"wk08-cutting","p":76,"q":"Water-jet cutting is used to cut virtually any material:","o":["Without heat or dust, with little waste or finishing","Only for metals thinner than about 1 mm","With a wide heat-affected zone along the cut edge of the part","Only for plastics and other soft materials like foam and rubber"],"h":"Clean, smooth cuts.","a":0,"id":466},{"d":"wk08-cutting","p":77,"q":"Water-jet cutting is low cost for production because:","o":["No tooling is needed for setup","It uses cheap, low-power lasers","It needs no water or abrasive","It cuts slowly with little wear"],"h":"No dies or punches.","a":0,"id":467},{"d":"wk08-cutting","p":80,"q":"Oxy-acetylene cutting can easily cut steel plates up to about:","o":["6 mm thick","25 mm thick","150 mm thick","1 m thick"],"h":"About 6 inches.","a":2,"id":468},{"d":"wk08-cutting","p":80,"q":"An advantage of oxy-acetylene cutting is:","o":["Portability, with no other power source","No gas tanks or hoses are needed","It gives the narrowest kerf of all thermal cutting methods","It runs from a high-voltage supply"],"h":"The tanks and hoses are a disadvantage.","a":0,"id":469},{"d":"wk08-cutting","p":81,"q":"In oxy-acetylene cutting, once the metal reaches critical temperature, increasing the oxygen flow:","o":["Oxidises the metal, making the cut","Cools the metal, stopping the cut","Hardens the cut edge for wear","Welds the plate back together"],"h":"It is burning, not melting alone.","a":0,"id":470},{"d":"wk08-cutting","p":82,"q":"The most popular method of thermal cutting, with higher temperatures than oxy-acetylene and the ability to cut non-ferrous and stainless steel, is:","o":["Laser beam machining","Plasma-arc cutting","Electron beam machining","Abrasive jet machining"],"h":"It needs a high-voltage power source.","a":1,"id":471},{"d":"wk08-cutting","p":83,"q":"A real advantage of plasma-arc cutting over oxy-acetylene is that it:","o":["It is compact and needs no bulky gas tanks","It needs no electrical power supply at all","It cuts much thicker steel than oxy-fuel","It is more portable for remote shipyards"],"h":"It requires a high-voltage power source instead.","a":0,"id":472},{"d":"wk08-cutting","p":87,"q":"Laser beam machining can drill holes as small as 0.005 mm with depth-to-diameter ratios of:","o":["1 to 1","5 to 1","50 to 1","500 to 1"],"h":"Used for the MacBook camera indicator holes.","a":2,"id":473},{"d":"wk08-cutting","p":86,"q":"In laser beam machining, the workpiece is:","o":["Melted and vaporised by focused energy","Eroded by repeated electrical sparks","Dissolved chemically in an electrolyte","Abraded by grit in a high-speed jet"],"h":"It does not require a vacuum.","a":0,"id":474},{"d":"wk08-cutting","p":89,"q":"Electron beam machining (EBM) differs from LBM mainly because it:","o":["Needs a vacuum and produces x-rays","Needs no power and no vacuum","Is cheaper and simpler to run than a laser","Cannot cut metals at all"],"h":"Electrons are accelerated to 80% of light speed.","a":0,"id":475},{"d":"wk08-cutting","p":90,"q":"Compared with other thermal cutting processes, laser and electron beam cutting have:","o":["Better finish, narrower kerf","Rougher finish, wider kerf","Lower accuracy, wider kerf","No heat input at the cut"],"h":"Extremely accurate cutting.","a":0,"id":476},{"d":"wk08-cutting","p":87,"q":"The tiny green camera light that shines through the MacBook's aluminium casing is made possible by holes produced by:","o":["Laser beam machining","Chemical milling","Abrasive water-jet cutting","Turret punching"],"h":"Micro-holes invisible to the eye.","a":0,"id":477},{"d":"wk09-joining","p":5,"q":"The three broad joining options available are:","o":["Thermo, adhesive and mechanical","Welding, soldering and brazing","Rivets, bolts and screws","Hot, warm and cold joining"],"h":"Fig: Joining family.","a":0,"id":478},{"d":"wk09-joining","p":6,"q":"Which is NOT listed as a consideration for choosing a joining process?","o":["Operator workwear colour","Joint strength and reliability","Appearance of the joint","Repair and maintenance needs"],"h":"Others include cost, quantity and facilities.","a":0,"id":479},{"d":"wk09-joining","p":7,"q":"The best strategy for joining is to:","o":["Minimise assembly through design for assembly","Weld every part so no fasteners are needed","Use as many fasteners as possible for strength","Avoid automation and keep assembly manual"],"h":"Assembly is a large share of production time.","a":0,"id":480},{"d":"wk09-joining","p":7,"q":"It is quite common for assembly or mechanical fastening to take more than ____ of total production time.","o":["5%","20%","50%","90%"],"h":"Assembly is time consuming.","a":2,"id":481},{"d":"wk09-joining","p":9,"q":"Mechanical fasteners usually represent less than ____ of the total in-place cost of a product, though assembly often accounts for the major manufacturing cost.","o":["5%","25%","50%","75%"],"h":"Fasteners are cheap; labour is not.","a":0,"id":482},{"d":"wk09-joining","p":9,"q":"When using mechanical fasteners, the cost of assembling a product is typically proportional to:","o":["The number of parts","The weight of the product","The cost of each fastener","The material density"],"h":"Fewer parts, lower assembly cost.","a":0,"id":483},{"d":"wk09-joining","p":14,"q":"In soldering and brazing:","o":["A third metal joins the parts without fusing them","The base metals are melted and fused together","No filler metal is used, only heat and pressure","Only thermoplastic parts can be joined this way"],"h":"The filler acts like a glue.","a":0,"id":484},{"d":"wk09-joining","p":15,"q":"Welding differs from soldering/brazing because:","o":["The base metals fuse, often changing their properties","It works at lower temperatures than soldering does","It cannot join metals, only thermoplastics","It needs no heat at all, only clamping pressure and vibration"],"h":"Heat treatment may be needed for a strong weld.","a":0,"id":485},{"d":"wk09-joining","p":16,"q":"Which is an advantage of soldering and brazing?","o":["Dissimilar metals and thicknesses can be joined","The joint is always stronger than the base metal","No flux is ever needed to prevent oxidation","They fuse the base metals for a seamless joint"],"h":"Cast and wrought metals can be joined too.","a":0,"id":486},{"d":"wk09-joining","p":17,"q":"Soldering is done at temperatures below:","o":["455°C","150°C","900°C","1230°C"],"h":"Brazing is above this temperature.","a":0,"id":487},{"d":"wk09-joining","p":17,"q":"Soldering is used primarily to:","o":["Conduct current and seal cans","Join structural steel beams","Join thick steel plates","Join thermoplastic parts"],"h":"Electronics and sealing.","a":0,"id":488},{"d":"wk09-joining","p":18,"q":"Flux is used in soldering to:","o":["Prevent oxidation so the solder bonds","Raise the melting point of the solder","Act as the filler metal in the joint","Cool the joint quickly after heating"],"h":"Clean surfaces bond.","a":0,"id":489},{"d":"wk09-joining","p":26,"q":"Because solder has little strength, soldered joints should be:","o":["Designed to carry load mechanically","Placed where stresses are highest","Made only on glass and ceramics","Always made as simple butt joints"],"h":"Mechanical interlock helps.","a":0,"id":490},{"d":"wk09-joining","p":26,"q":"Limited nonmetals such as glass can be soldered when:","o":["Pre-coated to accept solder","Heated above 1000°C first","Sandblasted to roughen them","Painted with a conductive primer"],"h":"The surface must be metallised.","a":0,"id":491},{"d":"wk09-joining","p":27,"q":"The common solder alloy used for electronics is:","o":["Tin-lead","Zinc-aluminium","Cadmium-zinc","Copper-phosphorus"],"h":"The classic electronics solder.","a":0,"id":492},{"d":"wk09-joining","p":28,"q":"Brazing is done at temperatures:","o":["Above 455°C, below the base metal melting point","Below 455°C, like soldering but with a stronger flux","Above the melting point of the base metals","At room temperature with a reactive paste and pressure"],"h":"Hotter than soldering.","a":0,"id":493},{"d":"wk09-joining","p":29,"q":"Brazing is stronger than soldering because:","o":["Limited alloying occurs between filler and base metals","The base metals melt and fuse completely into the filler","It uses no flux, so the joint is cleaner","It is done at a lower temperature than soldering, so less distortion"],"h":"Atomic forces at the joint.","a":0,"id":494},{"d":"wk09-joining","p":31,"q":"Which is an advantage of brazing?","o":["Assemblies can be joined in steps with lower-melting fillers","It needs extensive grinding and finishing afterwards","It produces high residual stresses in the parts being joined together","The finished joint does not conduct electricity"],"h":"Also stress-free and sealed joints.","a":0,"id":495},{"d":"wk09-joining","p":32,"q":"The filler metal used for brazing copper and its alloys is:","o":["Aluminium-silicon","Copper-phosphorus","Gold","Nickel-silver"],"h":"Brazed at 700-925°C.","a":1,"id":496},{"d":"wk09-joining","p":32,"q":"Aluminium alloys are typically brazed with which filler?","o":["Aluminium-silicon","Silver/copper","Gold","Magnesium-aluminium"],"h":"At 570-620°C.","a":0,"id":497},{"d":"wk09-joining","p":33,"q":"After brazing, flux residue must be removed because it is corrosive. The most common way is to:","o":["Quench it in a hot water bath","Sandblast the residue away","Leave the residue to evaporate","Paint over the flux residue"],"h":"Fluxes are sodium, potassium and lithium compounds.","a":0,"id":498},{"d":"wk09-joining","p":34,"q":"Torch brazing is common for:","o":["Most limited, manual production","High volume automated lines only","Very large structures only","Joining thermoplastic parts"],"h":"Uses a slightly reducing flame.","a":0,"id":499},{"d":"wk09-joining","p":37,"q":"Dip brazing of aluminium assemblies uses which heat source?","o":["An electrical coil","A molten salt bath","A hydrogen furnace","A laser"],"h":"The jigged assembly is dipped.","a":1,"id":500},{"d":"wk09-joining","p":38,"q":"In induction brazing, the heat source is:","o":["An electrical coil","A gas torch","A molten salt bath","Friction heating"],"h":"Normally automated, fast and uniform.","a":0,"id":501},{"d":"wk09-joining","p":39,"q":"No flux is necessary in furnace brazing because:","o":["Its hydrogen atmosphere has no oxygen","Its temperature is too low to oxidise","The parts are pre-painted against oxides","A molten salt bath shields the parts"],"h":"Flux prevents oxidation, which needs oxygen.","a":0,"id":502},{"d":"wk09-joining","p":40,"q":"In oxyacetylene gas welding, the metal pieces are heated:","o":["Above melting, so they flow together","Below melting, and joined by a filler","By an electric arc and a flux coating","By friction between the parts"],"h":"Fusion welding.","a":0,"id":503},{"d":"wk09-joining","p":43,"q":"In gas welding, pieces to be welded must be of similar:","o":["Thickness, melting point and metallurgy","Colour, texture and surface finish","Length, width and overall size of the parts","Hardness, cost and availability"],"h":"Unlike brazing.","a":0,"id":504},{"d":"wk09-joining","p":44,"q":"The stress caused as a gas-welded joint cools can be relieved by:","o":["Painting","Heat treatment","Quenching","Shot peening only"],"h":"Grain structure changes during welding.","a":1,"id":505},{"d":"wk09-joining","p":46,"q":"The most common method of arc welding, also called stick welding, is:","o":["SMAW","GMAW (MIG)","GTAW (TIG)","Plasma arc welding"],"h":"Uses a flux-covered electrode.","a":0,"id":506},{"d":"wk09-joining","p":47,"q":"In SMAW, the flux covering of the electrode:","o":["Shields the molten metal from oxidising","Acts as the tungsten tip that holds the arc","Cools the weld pool to limit distortion","Stays intact and is not consumed by the arc"],"h":"It forms slag.","a":0,"id":507},{"d":"wk09-joining","p":48,"q":"In stick welding, before another pass is made, the slag must be:","o":["Melted again","Removed by chipping","Painted","Left to protect the weld"],"h":"The melted flux collects on the weld.","a":1,"id":508},{"d":"wk09-joining","p":49,"q":"SMAW cannot be automated because of:","o":["Limited electrode length","Required gas tanks","High equipment cost","Very high precision of the arc"],"h":"The stick must be replaced as it is consumed.","a":0,"id":509},{"d":"wk09-joining","p":52,"q":"Gas metal arc welding (GMAW) is also called:","o":["MIG welding","TIG welding","Stick welding","Stud welding"],"h":"Uses a bare wire electrode fed from a reel.","a":0,"id":510},{"d":"wk09-joining","p":53,"q":"The real advantage of MIG welding over stick welding is:","o":["No slag to remove, so the weld stays clean","Lower equipment cost than stick welding","Greater maneuverability on site with no tanks or hoses","No shielding gas or flux is needed"],"h":"An inert gas shield replaces flux.","a":0,"id":511},{"d":"wk09-joining","p":53,"q":"Compared with stick welding, MIG welding:","o":["Costs more and is less maneuverable","Is cheaper and more maneuverable","Cannot be automated at all","Uses a non-consumable tungsten tip"],"h":"Trade-off for a cleaner weld.","a":0,"id":512},{"d":"wk09-joining","p":55,"q":"In stud arc welding:","o":["A stud serving as the electrode is fused to the surface","Two cylinders are rotated against each other until friction fuses them","Sheets are clamped and fused between two electrodes","A laser beam fuses the stud onto the plate"],"h":"Pull the trigger, melt, press, withdraw.","a":0,"id":513},{"d":"wk09-joining","p":58,"q":"Gas-tungsten arc welding (GTAW) is also called:","o":["TIG welding","MIG welding","Stick welding","Flash welding"],"h":"The electrode is tungsten.","a":0,"id":514},{"d":"wk09-joining","p":59,"q":"In TIG welding, the tungsten electrode:","o":["Is not consumed; a filler rod is added if needed","Melts and is consumed as the filler metal","Is coated with flux that forms a slag over the weld bead","Is fed continuously from a reel of wire"],"h":"Tungsten has a very high melting point.","a":0,"id":515},{"d":"wk09-joining","p":60,"q":"TIG welding is especially suited to:","o":["High-quality welds on thin sections and most metals","Fast, low-quality welds on very thick structural steel only","Joining thermoplastics without any filler","Field repairs in remote locations where no gas supply is available"],"h":"A precision process.","a":0,"id":516},{"d":"wk09-joining","p":61,"q":"Plasma arc welding achieves greater energy concentration because:","o":["The arc is forced through a small orifice","It uses a flux-coated consumable electrode","It operates inside a vacuum chamber","It runs at a lower current than TIG"],"h":"Not diffused as in other processes.","a":0,"id":517},{"d":"wk09-joining","p":62,"q":"Plasma arc welding temperatures can reach about:","o":["About 33,000°C","About 1,500°C","About 5,000°C","About 300°C"],"h":"Extremely hot.","a":0,"id":518},{"d":"wk09-joining","p":64,"q":"A disadvantage of plasma arc welding is:","o":["Complexity, needing two shielding gases","Longer welding time than other arc processes","More joint preparation than TIG","Less tolerance for joint mismatch and gaps"],"h":"Shielding is difficult.","a":0,"id":519},{"d":"wk09-joining","p":65,"q":"Resistance spot welding is widely used in:","o":["Sheet metal and car bodies","Joining thick iron castings","Plastic bottle seams","Glass-to-metal seals in lamps"],"h":"Simple, rapid and economical.","a":0,"id":520},{"d":"wk09-joining","p":66,"q":"Spot welding leaves small depressions at contact points; these can be reduced on the finish side by:","o":["Adjusting electrode pressure","Adding extra filler metal","Applying flux to the sheet","Increasing the current only"],"h":"The electrodes squeeze the sheets.","a":0,"id":521},{"d":"wk09-joining","p":69,"q":"In resistance projection welding (RPW), heat is localised by:","o":["Embossed projections on the sheet","A non-consumable tungsten electrode","A rotating spindle and friction","Immersion in a molten salt bath"],"h":"They collapse under heat and pressure.","a":0,"id":522},{"d":"wk09-joining","p":70,"q":"High-frequency (450 kHz) welding is used to produce:","o":["Continuous seams on steel tube","Spot welds on car body panels","Stud welds on plate","Lap welds on thin foil"],"h":"Rollers squeeze the tube sides together.","a":0,"id":523},{"d":"wk09-joining","p":73,"q":"Flash welding is commonly used in model shops to:","o":["Repair broken band saw blades","Weld thermoplastic housings","Spot weld thin sheet panels","Join glass to metal parts"],"h":"Ends are clamped and a 2000-5000 A current is applied.","a":0,"id":524},{"d":"wk09-joining","p":75,"q":"Ultrasonic bonding converts a high frequency of 10-75 kHz into:","o":["Mechanical vibration","Heat from an arc","Light energy","A chemical reaction"],"h":"Also commonly used to join plastics.","a":0,"id":525},{"d":"wk09-joining","p":75,"q":"Ultrasonic bonding is used for:","o":["Thin sheet, wire, foil packaging and plastics","Thick steel plate for structural building frames","Brazing copper pipes for plumbing","Joining thick cast iron machine parts"],"h":"Vibrations create the bond.","a":0,"id":526},{"d":"wk09-joining","p":78,"q":"Friction bonding is a solid state welding process used to join:","o":["Cylindrical parts, by spinning one against the other","Thin sheets, by clamping them between two copper electrodes","Foil packaging, by high-frequency vibration","Glass to metal, by a constricted plasma arc"],"h":"Heat comes from rubbing.","a":0,"id":527},{"d":"wk09-joining","p":81,"q":"An advantage of laser beam welding over electron beam welding is that LBW:","o":["Needs no vacuum and makes no x-rays","Needs a vacuum, so welds are cleaner","Produces more spatter but welds faster","Gives lower weld quality at lower cost"],"h":"Better weld quality too.","a":0,"id":528},{"d":"wk09-joining","p":81,"q":"The Gillette Mach3 razor's three narrow blades are joined by 33 pinpoint welds made by:","o":["Resistance spot welding","Ultrasonic welding","Nd:YAG laser beam welding","Stud welding"],"h":"0.5 mm diameter welds.","a":2,"id":529},{"d":"wk09-joining","p":8,"q":"Brazing, welding and adhesives are not economical to automate unless:","o":["Production quantity justifies it","The parts are made of plastic","The parts are very large and heavy","No tolerances are required"],"h":"Shipbuilding and oil rigs stay manual.","a":0,"id":530},{"d":"wk10-joining","p":56,"q":"The common technique used for joining acrylic parts using chloroform is a kind of ______ method.","o":["cyanoacrylate bonding","anaerobic bonding","epoxy bonding","solvent bonding"],"h":"The liquid dissolves the surfaces so they flow together.","a":3,"id":531},{"d":"wk10-joining","p":56,"q":"Solvent bonding is a common technique for joining parts moulded from:","o":["Amorphous thermoplastics","Crosslinked thermosets","Crystalline metals","Fired ceramics"],"h":"The solvent dissolves the mating surfaces.","a":0,"id":532},{"d":"wk10-joining","p":56,"q":"After solvent bonding and evaporation of the solvent, what remains is:","o":["A pure material bond","A thin layer of epoxy","A mechanical interlock","A residue of flux"],"h":"No foreign adhesive is left.","a":0,"id":533},{"d":"wk10-joining","p":56,"q":"Which is listed as an effective solvent for bonding ABS?","o":["Acetone, MEK or methylene chloride","Water with a wetting agent added","Molten sulfur","Ethanol, isopropyl alcohol or glycerine"],"h":"Common lab solvents.","a":0,"id":534},{"d":"wk10-joining","p":4,"q":"Which of the following is NOT a thermoplastic fusion joining method?","o":["Ultrasonic welding","Spin welding","Hot plate welding","Riveting"],"h":"Riveting is a mechanical method.","a":3,"id":535},{"d":"wk10-joining","p":5,"q":"Ultrasonic welding of thermoplastics provides strong, reliable bonds at very fast cycle times, but:","o":["Each job needs a custom horn and fixture","It cannot join any of the common amorphous or crystalline thermoplastics","It requires a flux at the interface","Its cycle times are very slow compared with adhesive bonding"],"h":"The horn transmits vibration.","a":0,"id":536},{"d":"wk10-joining","p":8,"q":"Which factor most influences successful ultrasonic welding?","o":["Uniform walls and simple shapes","The colour of the resin used","The use of a suitable flux","Long water cooling after welding"],"h":"Also resin grade, cleanliness, weld time and clamping pressure.","a":0,"id":537},{"d":"wk10-joining","p":9,"q":"Vibration welding works by:","o":["Rubbing parts together until friction melts the interface","Rotating one round part at high speed against another","Pressing the parts against a heated platen, then together","Heating a ferromagnetic gasket in a magnetic field"],"h":"Linear reciprocating friction.","a":0,"id":538},{"d":"wk10-joining","p":10,"q":"In vibration welding, mating part surfaces must be:","o":["Parallel and in one plane","Curved and irregular in profile","Coated with a flux before welding","Metallised beforehand"],"h":"The basic joint is a butt profile.","a":0,"id":539},{"d":"wk10-joining","p":11,"q":"An advantage of vibration welding is that the reciprocating motion:","o":["Pushes contaminants out of the weld area","Allows welding in several planes at once","Needs the cheapest equipment of any method","Needs no clamping pressure on the parts"],"h":"It is self-cleaning at the interface.","a":0,"id":540},{"d":"wk10-joining","p":11,"q":"A disadvantage of vibration welding is:","o":["Welds are usually limited to one plane","It cannot make hermetic or pressure-tight seals","It cannot weld internal walls","It can only handle very small parts, under a few centimetres"],"h":"Equipment cost is also higher.","a":0,"id":541},{"d":"wk10-joining","p":12,"q":"Spin welding joins thermoplastic parts by:","o":["Spinning one part against a fixed part","Vibrating the parts linearly together","Heating both faces with a platen","Dissolving the faces with a solvent"],"h":"Best for round parts.","a":0,"id":542},{"d":"wk10-joining","p":13,"q":"Which spin weld joint design tends to provide weaker bonds?","o":["Tongue and groove","Scarf joint","Shear joint","Butt joint"],"h":"The others give more bond area.","a":3,"id":543},{"d":"wk10-joining","p":14,"q":"Electromagnetic welding uses a gasket containing:","o":["Ferromagnetic particles in the same plastic","Chopped glass fibres dispersed in a two-part epoxy binder","Fine solder particles in a flux paste","Fine tungsten heating wire embedded in a silicone strip"],"h":"The particles heat up in an oscillating magnetic field.","a":0,"id":544},{"d":"wk10-joining","p":15,"q":"The electromagnetic welding process typically takes:","o":["Less than 0.1 seconds","3 to 10 seconds","15 to 20 minutes","Several hours"],"h":"Depends on weld area and resin.","a":1,"id":545},{"d":"wk10-joining","p":17,"q":"In hot plate welding:","o":["Parts are heated on a plate, which is removed before pressing","One part is spun at high speed against the other part under axial pressure","A solvent softens the faces before they are clamped","The parts are rubbed together in a linear motion until friction melts them"],"h":"Cycle usually 15-20 seconds.","a":0,"id":546},{"d":"wk10-joining","p":18,"q":"Hot plate welding usually uses which joint type due to the flat platens?","o":["Butt joints","Tongue and groove","Lap joints only","Scarf joints only"],"h":"Joint design is mainly for cosmetic bead hiding.","a":0,"id":547},{"d":"wk10-joining","p":19,"q":"Staking is:","o":["Deforming a plastic stud to capture a part","Welding two flat sheets with a vibrating horn","Inserting a metal thread into a plastic boss","Gluing parts together with cyanoacrylate"],"h":"Done with heat or ultrasonic energy.","a":0,"id":548},{"d":"wk10-joining","p":19,"q":"Ultrasonic staking is often chosen over heat staking because:","o":["The tip stays cool, giving clean heads without stringing","It is cheaper than heat staking in every application and every material","It uses no energy beyond the clamping force","It can stake metal studs and bosses as well as thermoplastic ones"],"h":"Heat staking can string.","a":0,"id":549},{"d":"wk10-joining","p":21,"q":"Which is NOT a thermoplastic mechanical assembly option?","o":["Press-fits","Snap fits","Moulded-in threads","Spin welding"],"h":"Spin welding is thermal fusion.","a":3,"id":550},{"d":"wk10-joining","p":22,"q":"With press-fits, there is no physical bond at the interface, so:","o":["They are always hermetic","A hermetic seal should not be expected","They cannot join dissimilar materials","Temperature has no effect"],"h":"Strength comes from mechanical interference.","a":1,"id":551},{"d":"wk10-joining","p":22,"q":"Press-fit joint strength can change with temperature because of:","o":["Different thermal expansion and creep","Solvent evaporation from the joint","Flux corrosion at the interface","Electrical conductivity of the parts"],"h":"Plastics and metals expand differently.","a":0,"id":552},{"d":"wk10-joining","p":24,"q":"Threaded inserts should be considered for plastic parts when:","o":["Parts must be taken apart often","The part will never be disassembled","The part is transparent","Solvent bonding is used"],"h":"Plastic threads wear out.","a":0,"id":553},{"d":"wk10-joining","p":26,"q":"Which insert installation methods are the fastest and easiest, but also the weakest?","o":["Press fit and expansion insertion","Ultrasonic and thermal insertion","Moulded-in insertion","Self-tapping insertion"],"h":"Little or no melting involved.","a":0,"id":554},{"d":"wk10-joining","p":28,"q":"In ultrasonic insertion of inserts:","o":["Vibration melts the plastic around the insert","The insert is placed in the mould before injection","The insert is bonded in with an adhesive","A screw expands the insert flanges outward"],"h":"The horn contacts the insert.","a":0,"id":555},{"d":"wk10-joining","p":30,"q":"A less expensive alternative to ultrasonic insertion is:","o":["Moulded-in insertion","Thermal insertion","Expansion insertion","Electromagnetic welding"],"h":"A heat source melts a thin layer.","a":1,"id":556},{"d":"wk10-joining","p":32,"q":"A major disadvantage of moulded-in inserts is:","o":["High stresses from metal/plastic thermal mismatch","They are the weakest of all insertion methods","They add nothing to cycle time or mould cost, so they are rarely chosen","They cannot be used with injection moulding, only compression moulding"],"h":"Thicker bosses are needed around them.","a":0,"id":557},{"d":"wk10-joining","p":33,"q":"Snap fits eliminate fasteners by using:","o":["The flexibility of moulded plastic","Adhesives applied at the hooks and latches","Heat to melt the parts together","Solvents that dissolve and bond the mating surfaces"],"h":"They can be one-time or multiple use.","a":0,"id":558},{"d":"wk10-joining","p":38,"q":"Mechanical fasteners are an excellent assembly option for plastics when:","o":["Appearance matters little or disassembly is needed","A hermetic seal is required at the joint under pressure","The parts are very thin and fragile","Invisible joints are needed on the visible cosmetic surface"],"h":"Strong, inexpensive and quick.","a":0,"id":559},{"d":"wk10-joining","p":39,"q":"The two classifications of self-tapping screws are:","o":["Thread forming and thread cutting","Machine screws and lag screws","Pan head and truss head","Blind, solid and semi-tubular screws"],"h":"Forming vs cutting the thread.","a":0,"id":560},{"d":"wk10-joining","p":40,"q":"Thread cutting screws are not used for repeated assembly because:","o":["Reinsertion may cut a second thread","They are too weak for most plastics","They induce high residual stresses","They are more expensive than inserts"],"h":"Care is needed to find the original thread.","a":0,"id":561},{"d":"wk10-joining","p":40,"q":"Thread forming screws can induce high residual stresses, which is acceptable in:","o":["Soft, ductile plastics","Brittle plastics","Glass and ceramics","All plastics equally"],"h":"The stresses eventually subside.","a":0,"id":562},{"d":"wk10-joining","p":41,"q":"In clamped fastener designs in plastics, stress relaxation over time may cause screws to back off. This can be helped by:","o":["Locking fasteners and washers","Thread cutting screws in place of forming ones","Heating the joint","Removing the boss and screwing directly into the wall"],"h":"Spread the load.","a":0,"id":563},{"d":"wk10-joining","p":43,"q":"When riveting plastics, aluminium rivets are preferred over steel because:","o":["Aluminium deforms more easily","Aluminium rivets are stronger","Aluminium conducts heat away","Aluminium rivets are cheaper"],"h":"Reduces stress on the plastic.","a":0,"id":564},{"d":"wk10-joining","p":43,"q":"To reduce stress concentrations when riveting plastic parts, it is suggested to use:","o":["Large heads, washers and radiused corners","Small heads, no washers and sharp corners","Steel rivets driven with high force","Rivets placed as close to edges as possible"],"h":"Distribute stresses.","a":0,"id":565},{"d":"wk10-joining","p":47,"q":"Synthetic organic adhesives are often used for:","o":["Load bearing, thin materials and invisible joints","Joints that are loaded mainly in peel or cleavage","High-temperature furnace components only","Joints that must reliably conduct electricity and heat"],"h":"Strength, toughness and environmental resistance are needed.","a":0,"id":566},{"d":"wk10-joining","p":48,"q":"An adhesive joint should be designed to withstand shear, compressive and tensile forces, but should NOT be subjected to:","o":["Shear","Compression","Peeling","Tension"],"h":"Labels come off by peeling.","a":2,"id":567},{"d":"wk10-joining","p":50,"q":"Which is an advantage of adhesives?","o":["Even stress distribution, dissimilar materials","Unlimited shelf life of the adhesive once opened","Simple non-destructive joint testing","No need for any surface cleaning or preparation beforehand"],"h":"Also seal and dampen.","a":0,"id":568},{"d":"wk10-joining","p":51,"q":"Which is a disadvantage of adhesives?","o":["Limited shelf life, destructive testing","They deface exposed surfaces with holes and heads","They cannot join thin parts","They concentrate stress at points around each joint"],"h":"Also need thorough cleaning.","a":0,"id":569},{"d":"wk10-joining","p":57,"q":"Adhesive bonding is convenient for joining plastic to similar or dissimilar materials, and can provide:","o":["A hermetic seal with spread-out stress","Only weak, temporary bonds that peel easily","Electrical conduction in all cases","Easy disassembly of the joint without any damage"],"h":"Loctite and ThreeBond are suppliers.","a":0,"id":570},{"d":"wk10-joining","p":58,"q":"Typical screening of an adhesive with a particular substrate consists of:","o":["Compatibility and adhesion testing","An x-ray test and a colour test","A hardness test and a creep test","A single peel test at room temperature"],"h":"Two tests.","a":0,"id":571},{"d":"wk10-joining","p":59,"q":"Two-part epoxies consist of:","o":["Resin and hardener in fixed ratio","A primer and a separate catalyst","A solvent and a dissolved resin","Moisture and a reactive monomer"],"h":"One-part epoxies need heat curing instead.","a":0,"id":572},{"d":"wk10-joining","p":59,"q":"One-part epoxies require curing by heat, usually around:","o":["148°C for one hour or more","Room temperature for about 10 seconds","1000°C for 1 minute","UV light exposure for about 3 seconds"],"h":"No mixing but heat is needed.","a":0,"id":573},{"d":"wk10-joining","p":59,"q":"Unlike many other adhesives, epoxies:","o":["Cure by chemical reaction","Cure without oxygen","Cure from surface moisture","Cure only under UV light"],"h":"A chemical crosslinking reaction.","a":0,"id":574},{"d":"wk10-joining","p":60,"q":"Urethane adhesives are primarily used in applications requiring:","o":["Strength with flexibility","Setting within seconds","Curing without oxygen","No mixing of components"],"h":"Polyurethanes.","a":0,"id":575},{"d":"wk10-joining","p":60,"q":"Anaerobic adhesives cure when triggered by:","o":["The presence of surface moisture","The absence of oxygen","UV light only","Mixing with a hardener"],"h":"Used for threadlockers.","a":1,"id":576},{"d":"wk10-joining","p":61,"q":"Cyanoacrylate (super glue) curing is initiated by:","o":["Surface moisture","Absence of oxygen","Heat above 148°C","Mixing two parts"],"h":"Sets in 2-3 seconds.","a":0,"id":577},{"d":"wk10-joining","p":61,"q":"Cyanoacrylates have a normal setting time of ____ and full cure in ____.","o":["2-3 seconds; 24 hours","60-90 seconds; 30 minutes","15 seconds; 2-24 hours","5 minutes; 1 hour"],"h":"Convenience adhesives.","a":0,"id":578},{"d":"wk10-joining","p":61,"q":"UV curable adhesives use light energy to initiate polymerisation, typically curing in:","o":["3 to 10 seconds","24 hours","1 hour at 148°C","30 minutes"],"h":"Extremely fast.","a":0,"id":579},{"d":"wk10-joining","p":62,"q":"\"Improved\" acrylic adhesives offer the advantage of:","o":["Rarely needing primers","Curing without catalyst","Working as solvent bonds","Bonding metals only"],"h":"Full cure within 30 minutes.","a":0,"id":580},{"d":"wk10-joining","p":64,"q":"In flame treatment as a surface preparation for adhesives, the surface is exposed to:","o":["The blue oxidising zone","The yellow luminous zone","A UV curing lamp","An acid etching bath"],"h":"Oxidises the surface.","a":0,"id":581},{"d":"wk10-joining","p":64,"q":"Corona discharge surface treatment involves:","o":["Ion bombardment between two electrodes","Dipping the part in an acid bath","Sanding the surface with abrasives","Exposing it to inert gas in a vacuum"],"h":"Electrical surface activation.","a":0,"id":582},{"d":"wk10-joining","p":64,"q":"Which surface preparation places the substrate in a vacuum chamber filled with inert gas under high electrical tension?","o":["Corona discharge","Plasma treatment","Chemical etch","Flame treatment"],"h":"Similar surface oxidation results.","a":1,"id":583},{"d":"wk10-joining","p":66,"q":"Standardisation of fasteners is recommended because:","o":["Handling many fastener sizes costs more than the screws","Using many different sizes is always cheaper per part assembled","It increases the part count and so the strength","It allows a wider range of fastener colours and finishes to be used"],"h":"Saving a few cents per screw is false economy.","a":0,"id":584},{"d":"wk10-joining","p":68,"q":"The most common fasteners used in assembly are:","o":["Threaded fasteners","Rivets","Staples","Moulded-in snap fits"],"h":"Drill and tap for a machine screw.","a":0,"id":585},{"d":"wk10-joining","p":70,"q":"Fasteners for insertion into sheet metal are commonly called \"pems\", after:","o":["Penn Engineering and Manufacturing","Press-fit Embedded Metal fasteners","Pneumatic Electrical Machines Inc.","Permanent Embossed Mounts"],"h":"One of the first developers.","a":0,"id":586},{"d":"wk10-joining","p":75,"q":"A rivet makes a joint by:","o":["Clamping parts between two heads, one upset","Melting the base metals together around the hole","Gluing the parts with a rivet adhesive","Threading into a tapped hole in the mating part"],"h":"Solid or hollow.","a":0,"id":587},{"d":"wk10-joining","p":76,"q":"Blind (pop) rivets are:","o":["Inserted from one side and set by pulling a mandrel","Solid rivets formed by hot upsetting on both sides","Rivets that become invisible once painted over","Threaded inserts pressed into sheet metal"],"h":"Only one side needs access.","a":0,"id":588},{"d":"wk10-joining","p":77,"q":"Because a rivet hole is a discontinuity that could cause fatigue failure, in critical applications the hole is:","o":["Reamed or expanded for compressive stress","Left rough so the rivet grips the sheet better","Welded shut once the rivet is set","Drilled well oversize to give clearance for expansion"],"h":"Remove stress raisers.","a":0,"id":589},{"d":"wk10-joining","p":77,"q":"Riveting remains of great importance in:","o":["Aircraft","Building frames","Car chassis","Plastic toys"],"h":"It has lost dominance elsewhere.","a":0,"id":590},{"d":"wk10-joining","p":79,"q":"Thin sheets can be joined without preliminary drilling by:","o":["Stitching or stapling","Solid riveting","Bolting","Pressed-in threaded inserts"],"h":"Common for sheet to wooden backing.","a":0,"id":591},{"d":"wk10-joining","p":80,"q":"Seams are produced by a sequence of bends on tight radii of about:","o":["Five sheet thicknesses","One-half sheet thickness","Ten sheet thicknesses","Zero"],"h":"Lock seams can be sealed with fillers.","a":1,"id":592},{"d":"wk10-joining","p":72,"q":"Non-threaded fasteners are often invisible because they are held by friction within the assembly. The most common visible one is the:","o":["Rivet","Washer","Pin","Retaining ring"],"h":"It sits under a screw head.","a":1,"id":593},{"d":"wk13-ceramics","p":4,"q":"Ceramic materials are:","o":["Inorganic, nonmetallic compounds with mainly ionic bonds","Organic compounds built on long covalent carbon chains","Metallic elements held together by a sea of electrons","Amorphous polymers crosslinked into a rigid network"],"h":"Compounds between metallic and nonmetallic elements.","a":0,"id":594},{"d":"wk13-ceramics","p":4,"q":"The word ceramic comes from the Greek \"keramikos\", meaning:","o":["Hard stone","Burnt stuff","Clay pot","Glass"],"h":"Properties are achieved by firing.","a":1,"id":595},{"d":"wk13-ceramics","p":4,"q":"A covalent bond involves:","o":["Electrostatic attraction between oppositely charged ions","Electron sharing between atoms","A sea of free electrons","Weak van der Waals attraction only"],"h":"It is short range.","a":1,"id":596},{"d":"wk13-ceramics","p":5,"q":"Ceramic engine components permit efficient burning of fuel at higher temperatures and can:","o":["Remove the need for a cooling system","Conduct electricity to the spark plugs","Be easily welded onto the engine block","Absorb shocks better than steel parts"],"h":"They withstand extreme heat.","a":0,"id":597},{"d":"wk13-ceramics","p":7,"q":"Engineering ceramics are low in cost mainly because:","o":["They are easy to machine","Raw materials are abundant","They need no firing","They are recycled plastics"],"h":"Clay and sand are everywhere.","a":1,"id":598},{"d":"wk13-ceramics","p":7,"q":"The brittleness of ceramics has been reduced by new combinations with:","o":["Fibres or whiskers","Plasticisers","Lead oxide","Water and binders"],"h":"Ceramic matrix composites.","a":0,"id":599},{"d":"wk13-ceramics","p":7,"q":"The three main types of engineering ceramics are:","o":["Oxides, glass ceramics, and carbides/nitrides","Earthenware, stoneware, porcelain and bone china","Soft, hard and very hard glasses","Alumina, zirconia, beryllia and other oxide ceramics"],"h":"Categories A, B and C.","a":0,"id":600},{"d":"wk13-ceramics","p":8,"q":"Aluminas are a family of:","o":["Aluminium oxides","Silicon carbides","Zirconium oxides","Boron nitrides"],"h":"They serve at 1650°C.","a":0,"id":601},{"d":"wk13-ceramics","p":8,"q":"Which metal oxide ceramic resists thermal shock with low thermal expansion and high thermal conductivity?","o":["Alumina","Beryllia","Zirconia","Silica"],"h":"Beryllium oxide (BeO).","a":1,"id":602},{"d":"wk13-ceramics","p":8,"q":"Zirconia is noted for:","o":["Inertness to metals and strength up to 2204°C","Poor strength above a few hundred degrees Celsius","Being a glass ceramic used for cooktops and cookware","Being the main bulletproof armour ceramic"],"h":"A tough oxide ceramic.","a":0,"id":603},{"d":"wk13-ceramics","p":9,"q":"Glass ceramics are formed by:","o":["Crystallising formed glass by heat treatment","Pressing powder in a die, then sintering it","Chemical vapour deposition onto a substrate","Vulcanising with sulfur at high temperature"],"h":"Used for cooktops and cookware.","a":0,"id":604},{"d":"wk13-ceramics","p":9,"q":"Glass ceramics have:","o":["Near-zero thermal expansion","Very high thermal expansion","High electrical conductivity","Low corrosion resistance"],"h":"They can go from freezer to oven.","a":0,"id":605},{"d":"wk13-ceramics","p":10,"q":"Macor by Corning is a glass ceramic notable because it:","o":["Can be machined with ordinary tools","Is transparent like window glass","Is magnetic like ferrite ceramics","Melts at only about 200°C"],"h":"It has the strength of alumina.","a":0,"id":606},{"d":"wk13-ceramics","p":12,"q":"Boron carbide, with very high hardness and low density, is used for:","o":["Armour plate and blasting nozzles","Ovenware and stovetop cookware","Window and display glass","Heart valve and joint implant coatings"],"h":"Excellent abrasion resistance.","a":0,"id":607},{"d":"wk13-ceramics","p":13,"q":"The general steps in forming ceramics are:","o":["Grind, mix with additives, shape, dry and fire","Melt, cast into a mould, quench and then temper","Polymerise, mould, then cure in an oven","Forge, roll, heat treat, then machine to final size"],"h":"Fine particles first.","a":0,"id":608},{"d":"wk13-ceramics","p":14,"q":"The three basic forming processes for ceramics are:","o":["Casting, plastic forming and pressing","Forging, rolling and extrusion","Blowing, drawing, floating and rolling","Turning, milling and grinding"],"h":"LSF, plastic state, SSF.","a":0,"id":609},{"d":"wk13-ceramics","p":15,"q":"In slip casting, a suspension of ceramic particles in water is poured into a:","o":["Porous plaster mould","Steel die under pressure","Bath of molten tin","Rotating steel mandrel"],"h":"Excess slip is poured out.","a":0,"id":610},{"d":"wk13-ceramics","p":16,"q":"Slip casting is characterised by:","o":["Low rate and limited accuracy, but low cost","High rate and tight dimensional control","Very expensive tooling needed for each new design","Only small, simple parts can be made"],"h":"Used for bathroom products and dinnerware.","a":0,"id":611},{"d":"wk13-ceramics","p":17,"q":"Which of the following is a plastic (soft/hydroplastic) forming process for ceramics?","o":["Slip casting","Dry pressing","Jiggering","Float process"],"h":"Also extrusion and injection moulding.","a":2,"id":612},{"d":"wk13-ceramics","p":17,"q":"Plastic state forming processes for ceramics tend to:","o":["Align clay layers with the flow","Produce a random particle orientation","Eliminate drying shrinkage","Require molten material"],"h":"Like grain flow.","a":0,"id":613},{"d":"wk13-ceramics","p":18,"q":"Dry pressing is used for simple ceramic shapes such as:","o":["Floor tiles and refractories","Bathroom sinks and toilets","Glass bottles and jars","Optical fibres and wool"],"h":"Similar to powder-metal compaction.","a":0,"id":614},{"d":"wk13-ceramics","p":19,"q":"In wet pressing of ceramics, dimensional control is difficult because of:","o":["Shrinkage during drying","Too little pressing pressure","Contact with molten tin","Lack of a closed mould"],"h":"High production rates though.","a":0,"id":615},{"d":"wk13-ceramics","p":19,"q":"In hot pressing (pressure sintering), applying pressure and temperature simultaneously:","o":["Reduces porosity for a denser, stronger part","Increases porosity for a lighter part","Fully melts the ceramic powder into a glass","Makes the part optically transparent"],"h":"Combined compaction and firing.","a":0,"id":616},{"d":"wk13-ceramics","p":20,"q":"Jiggering is limited to:","o":["Symmetrical parts of limited accuracy","Asymmetrical parts of high accuracy","Flat sheets of uniform thickness","Thin continuous fibres and rods"],"h":"Clay is shaped on a rotating mould with templates.","a":0,"id":617},{"d":"wk13-ceramics","p":21,"q":"In ceramic injection moulding, the thermoplastic binder is removed by:","o":["Pyrolysis before sintering","Washing out in water","Machining it away after firing","Chemical tempering"],"h":"Burnt out with heat.","a":0,"id":618},{"d":"wk13-ceramics","p":22,"q":"Shrinkage of ceramic parts during drying and firing can be up to about:","o":["1%","5%","20%","50%"],"h":"Of the original wet size.","a":2,"id":619},{"d":"wk13-ceramics","p":22,"q":"Ceramic parts tend to warp or crack during drying and firing because of:","o":["Uneven moisture from varied walls and shapes","Too little moisture in the raw clay mix","Lack of binder holding the particles together during firing","Rapid quenching after the firing cycle"],"h":"Uniform walls help.","a":0,"id":620},{"d":"wk13-ceramics","p":22,"q":"Firing (sintering) a ceramic:","o":["Bonds the particles and reduces porosity","Reduces strength by growing large pores","Melts the whole part into a glass","Removes the hardness of the oxide"],"h":"Similar to powder metallurgy sintering.","a":0,"id":621},{"d":"wk13-ceramics","p":23,"q":"A glaze fired onto a ceramic product gives a glassy coat that:","o":["Improves looks and strength, sealing the surface","Makes the surface electrically conductive","Makes the body flexible and tough","Reduces surface hardness so the part is easier to machine"],"h":"A final finishing step.","a":0,"id":622},{"d":"wk13-ceramics","p":24,"q":"Glass is:","o":["An amorphous solid, resistant to most chemicals except HF","A crystalline metal oxide with a regular lattice structure","A thermoset polymer crosslinked during cooling","A ductile ceramic that yields before it fractures"],"h":"HF etches glass.","a":0,"id":623},{"d":"wk13-ceramics","p":24,"q":"Glass is composed mainly of:","o":["Silica, lime and soda","Alumina, zirconia and boron","Carbon, coke and graphite","Iron oxide and carbon"],"h":"Sand, limestone and soda ash.","a":0,"id":624},{"d":"wk13-ceramics","p":26,"q":"The glass transition temperature (Tg) is the temperature at which an amorphous solid:","o":["Turns brittle on cooling or soft on heating","Begins to boil and give off vapour","Crystallises into an ordered, regular atomic lattice","Loses its transparency and turns opal"],"h":"For soda-lime glass, 520-600°C.","a":0,"id":625},{"d":"wk13-ceramics","p":26,"q":"Soda-lime glass accounts for about ____ of all glass produced.","o":["10%","50%","90%","99.9%"],"h":"Bottles, windows, light bulbs.","a":2,"id":626},{"d":"wk13-ceramics","p":26,"q":"A limitation of soda-lime glass is that it:","o":["Has poor resistance to heat, thermal shock and chemicals","Is very expensive compared with other glasses","Cannot be made transparent without additives","Has the highest thermal shock resistance of all glasses"],"h":"It is a soft glass.","a":0,"id":627},{"d":"wk13-ceramics","p":28,"q":"Lead-alkali glass is called \"crystal\" because of its:","o":["Crystalline atomic structure","High index of refraction","Hardness","Heat resistance"],"h":"It is still amorphous.","a":1,"id":628},{"d":"wk13-ceramics","p":28,"q":"Lead glass is used to shield:","o":["Ultraviolet light","Atomic radiation","Magnetic fields","Sound"],"h":"Lead absorbs radiation.","a":1,"id":629},{"d":"wk13-ceramics","p":29,"q":"Borosilicate glass (e.g. Pyrex) is preferred over soda-lime glass for laboratory glassware mainly because it:","o":["Has better resistance to thermal shock and heat","Is cheaper to produce and easier to melt","Has a higher coefficient of thermal expansion","Is denser, giving a more brilliant sparkle"],"h":"Developed in 1912 as the first thermal-shock-resistant glass.","a":0,"id":630},{"d":"wk13-ceramics","p":29,"q":"Borosilicate glass is classified as a:","o":["Soft glass","Hard glass","Very hard glass","Light-sensitive glass"],"h":"It softens at relatively high temperatures.","a":1,"id":631},{"d":"wk13-ceramics","p":31,"q":"Aluminosilicate glass, used in space-vehicle windows and high-temperature thermometers, compared with borosilicate:","o":["Costs more and is harder to fabricate","Is cheaper and easier to fabricate and shape","Has lower heat resistance","Is classed as a soft glass, like soda-lime"],"h":"High performance applications.","a":0,"id":632},{"d":"wk13-ceramics","p":33,"q":"The most expensive of all glasses, with maximum thermal shock resistance, is:","o":["Borosilicate","Lead crystal","Fused silica","Soda-lime"],"h":"Pure silicon dioxide.","a":2,"id":633},{"d":"wk13-ceramics","p":32,"q":"96% silica glass can withstand:","o":["Atmospheric re-entry heat","Only room temperatures","Hydrofluoric acid attack","Bending like a metal"],"h":"Used on space shuttle exteriors.","a":0,"id":634},{"d":"wk13-ceramics","p":34,"q":"Photochromic glass is used for:","o":["Sunglasses that darken in UV light","Permanent colour information storage","Turning permanently from clear to opal","Shielding against atomic radiation"],"h":"Transition lenses.","a":0,"id":635},{"d":"wk13-ceramics","p":34,"q":"Photosensitive glass:","o":["Turns opal when exposed to UV and heated","Darkens in sunlight and fades again indoors","Is used for lead crystal tableware","Is a standard soda-lime window glass"],"h":"Can be chemically machined.","a":0,"id":636},{"d":"wk13-ceramics","p":37,"q":"Glass sheet made by the rolling process has:","o":["A rough or roller-textured surface","A perfect fire-polished finish","No need for any further finishing or polishing","A tin-coated underside"],"h":"Similar to calendering of plastics.","a":0,"id":637},{"d":"wk13-ceramics","p":38,"q":"In the float process for flat glass, molten glass floats on a bath of:","o":["Water","Molten tin","Molten lead","Oil"],"h":"It is fire polished in the lehr and needs no further polishing.","a":1,"id":638},{"d":"wk13-ceramics","p":38,"q":"Float glass needs no further polishing because:","o":["It is ground after forming","It is fire polished as it solidifies","It is chemically etched","It is rolled with textured rollers"],"h":"The tin bath is perfectly flat.","a":1,"id":639},{"d":"wk13-ceramics","p":39,"q":"Glass tubing is formed around a rotating mandrel, kept open by:","o":["Air blown through the mandrel","A ceramic core inside the tube","A bath of molten tin","A plunger pressing the gob"],"h":"Solid rods are made without air.","a":0,"id":640},{"d":"wk13-ceramics","p":40,"q":"Glass fibres for fibre-optic cable are made by a process similar to:","o":["Wire drawing","The float process","Glass pressing","Slip casting"],"h":"Drawn at up to 520 m/s.","a":0,"id":641},{"d":"wk13-ceramics","p":40,"q":"Thermal and acoustic insulating glass wool is made by:","o":["Centrifugal spinning","The float process","Glass pressing","Sheet rolling between rollers"],"h":"Fine fibres are spun out.","a":0,"id":642},{"d":"wk13-ceramics","p":42,"q":"Glass blowing is used for thin walled containers and light bulbs, but a limitation is that:","o":["Wall thickness can't be controlled","The surface finish is unacceptable","It is very slow for bulbs","It cannot be automated"],"h":"Machines can make over 1000 bulbs per minute.","a":0,"id":643},{"d":"wk13-ceramics","p":43,"q":"Glass pressing forms simple open shapes with good accuracy, but cannot be used for:","o":["Thin-walled or closed shapes","Thick, solid open parts","Shallow open dishes and bowls","Lenses and reflectors"],"h":"A plunger forces a gob into a mould.","a":0,"id":644},{"d":"wk13-ceramics","p":44,"q":"TV picture tubes and missile nose cones are made by glass:","o":["Centrifugal casting","Blowing","Sagging","The float process"],"h":"Symmetrical products.","a":0,"id":645},{"d":"wk13-ceramics","p":45,"q":"Sagging is an inexpensive process in which:","o":["Hot sheet slumps into a mould by gravity","Glass is blown into a mould with air","Glass is floated on a bath of molten tin","Glass is drawn through orifices into fibres"],"h":"Dishes, lighting diffusers, sunglass lenses.","a":0,"id":646},{"d":"wk13-ceramics","p":46,"q":"Thermally tempered glass, when broken:","o":["Shatters into small pieces","Holds together on a plastic layer","Breaks into large sharp shards","Bends without breaking"],"h":"Car side windows.","a":0,"id":647},{"d":"wk13-ceramics","p":46,"q":"Chemical tempering of glass works by:","o":["Ion exchange in a molten salt bath","Rapid air chilling of the surface","Laminating plastic between sheets","Slow annealing to relieve stress"],"h":"A longer-term process.","a":0,"id":648},{"d":"wk13-ceramics","p":46,"q":"Laminated glass, commonly used for automotive windscreens, consists of:","o":["Plastic between two glass sheets","Two tempered sheets bonded with epoxy","Glass coated on one side with tin","A single chemically tempered sheet"],"h":"The plastic holds pieces if broken.","a":0,"id":649},{"d":"wk13-ceramics","p":47,"q":"Glass sheet is usually \"cut\" by scoring and snapping, which exploits its:","o":["Ductility","Notch sensitivity","Thermal shock resistance","Self-lubrication"],"h":"It breaks along the score.","a":1,"id":650},{"d":"wk13-ceramics","p":48,"q":"Manufactured carbon is composed of:","o":["Coke and graphite bonded with carbon","Pure diamond grown by vapour deposition","Silicon carbide and boron sintered together","Carbon fibre bonded in an epoxy matrix"],"h":"Used for motor brushes.","a":0,"id":651},{"d":"wk13-ceramics","p":48,"q":"Which is a property of manufactured carbon?","o":["Self-lubricating and conductive","An excellent electrical insulator","Highly ductile and malleable","Easily attacked by solvents"],"h":"Slides on metals without galling.","a":0,"id":652},{"d":"wk13-ceramics","p":49,"q":"Manufactured carbon is brittle but:","o":["Is not notch sensitive and resists fatigue well","Is highly notch sensitive and fatigues easily","Has poor fatigue resistance compared with metals","Can easily be welded to repair cracks"],"h":"Scratches don't weaken it much.","a":0,"id":653},{"d":"wk13-ceramics","p":50,"q":"A classic application of manufactured carbon is:","o":["Electric motor brushes","Window and display glass","Bulletproof armour plate","Ovenware and cookware"],"h":"Conductive and self-lubricating.","a":0,"id":654},{"d":"wk13-ceramics","p":51,"q":"Pyrolytic carbon coatings for heart valves are made by:","o":["Chemical vapour deposition in a fluidised bed","Slip casting into a porous plaster mould","Injection moulding with a thermoplastic binder","Sintering of pressed carbon powder"],"h":"Co-depositing onto substrates.","a":0,"id":655},{"d":"wk13-ceramics","p":53,"q":"Carbon-reinforced plastics are replacing metals in aerospace for:","o":["Weight saving and damping","Lower stiffness than metal","Electrical insulation","Ease of welding repairs"],"h":"Usage rose from 13% to 54% in one generation.","a":0,"id":656},{"d":"wk13-ceramics","p":54,"q":"Refractory hard metals (RHMs) are:","o":["Carbide particles in a metal matrix","Pure tungsten castings","Glass ceramics with metal oxides","Carbon fibre bonded in an epoxy matrix"],"h":"Cemented carbides.","a":0,"id":657},{"d":"wk13-ceramics","p":54,"q":"Compared with ceramics, RHMs are:","o":["More ductile and shock resistant, but weaker when hot","More brittle, but stronger at high temperatures","Higher in maximum operating temperature than any ceramic","Softer than steel and easier to machine"],"h":"Trade-offs between metal and ceramic.","a":0,"id":658},{"d":"wk13-ceramics","p":55,"q":"The most common structural RHM, used for saw blade tips, is:","o":["Titanium carbide","Tungsten carbide","Tantalum carbide","Boron carbide"],"h":"High-cobalt grades for impact resistance.","a":1,"id":659},{"d":"wk13-ceramics","p":55,"q":"RHM parts are made by:","o":["Powder compacting and sintering","Sand casting and machining","Hot forging in closed dies","Lost-wax investment casting"],"h":"Like other carbide tooling.","a":0,"id":660},{"d":"wk13-ceramics","p":55,"q":"Which RHM is used for metal-forming tooling such as draw dies and burnishing rolls?","o":["Tungsten-titanium carbide","Tungsten carbide (high cobalt)","Titanium carbide","Tantalum carbide"],"h":"The combination system.","a":0,"id":661}];
